FOR change IN SELECT a.j AS old_j,b.j AS new_j FROM jsonb_array_elements(coalesce(o->'edit_history','[]')) a(j) FULL JOIN jsonb_array_elements(coalesce(n->'edit_history','[]')) b(j) ON og70_key('review_revisions',a.j)=og70_key('review_revisions',b.j) WHERE a.j IS DISTINCT FROM b.j LOOP
 operation:=CASE WHEN change.new_j IS NULL THEN 'DELETE' WHEN change.old_j IS NULL THEN 'INSERT' ELSE 'UPDATE' END;
 IF phase='BEFORE' THEN
  IF coalesce(current_setting('og70.prepared',true),'')<>'review_revisions' THEN RAISE EXCEPTION 'Change aggregate history through its workflow operation' USING ERRCODE='23514'; END IF;
