--
-- Name: og70_hooks(text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_hooks(s text, p_op text, p_phase text, p_new jsonb, p_old jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE previous text:=coalesce(nullif(current_setting('og70.depth',true),''),'0');
 depth integer:=previous::integer+1; result jsonb;
BEGIN
 PERFORM set_config('og70.depth',depth::text,true);
 CASE s
WHEN 'carts' THEN
