--
-- Name: og70_key(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_key(s text, j jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$ BEGIN CASE s WHEN 'carts' THEN RETURN jsonb_build_array(j->'cart_id');
WHEN 'cases' THEN RETURN jsonb_build_array(j->'case_id');
WHEN 'roles' THEN RETURN jsonb_build_array(j->'role_id');
WHEN 'users' THEN RETURN jsonb_build_array(j->'user_id');
WHEN 'offers' THEN RETURN jsonb_build_array(j->'offer_id');
WHEN 'orders' THEN RETURN jsonb_build_array(j->'order_id');
WHEN 'reports' THEN RETURN jsonb_build_array(j->'report_id');
WHEN 'reviews' THEN RETURN jsonb_build_array(j->'review_id');
WHEN 'messages' THEN RETURN jsonb_build_array(j->'message_id');
WHEN 'payments' THEN RETURN jsonb_build_array(j->'payment_id');
WHEN 'products' THEN RETURN jsonb_build_array(j->'product_id');
WHEN 'vouchers' THEN RETURN jsonb_build_array(j->'voucher_id');
WHEN 'addresses' THEN RETURN jsonb_build_array(j->'address_id');
WHEN 'shipments' THEN RETURN jsonb_build_array(j->'shipment_id');
WHEN 'audit_logs' THEN RETURN jsonb_build_array(j->'log_id');
WHEN 'cart_items' THEN RETURN jsonb_build_array(j->'cart_id',j->'product_id');
WHEN 'categories' THEN RETURN jsonb_build_array(j->'category_id');
WHEN 'complaints' THEN RETURN jsonb_build_array(j->'complaint_id');
WHEN 'user_roles' THEN RETURN jsonb_build_array(j->'user_id',j->'role_id');
WHEN 'case_events' THEN RETURN jsonb_build_array(j->'event_id');
WHEN 'case_rounds' THEN RETURN jsonb_build_array(j->'round_id');
WHEN 'money_holds' THEN RETURN jsonb_build_array(j->'hold_id');
WHEN 'order_items' THEN RETURN jsonb_build_array(j->'order_item_id');
WHEN 'order_events' THEN RETURN jsonb_build_array(j->'event_id');
WHEN 'case_evidence' THEN RETURN jsonb_build_array(j->'evidence_id');
WHEN 'conversations' THEN RETURN jsonb_build_array(j->'conversation_id');
WHEN 'ekyc_profiles' THEN RETURN jsonb_build_array(j->'profile_id');
WHEN 'notifications' THEN RETURN jsonb_build_array(j->'notification_id');
WHEN 'outbox_events' THEN RETURN jsonb_build_array(j->'event_id');
WHEN 'product_media' THEN RETURN jsonb_build_array(j->'media_id');
WHEN 'reward_ledger' THEN RETURN jsonb_build_array(j->'entry_id');
WHEN 'case_decisions' THEN RETURN jsonb_build_array(j->'decision_id');
WHEN 'ekyc_decisions' THEN RETURN jsonb_build_array(j->'decision_id');
WHEN 'order_vouchers' THEN RETURN jsonb_build_array(j->'order_voucher_id');
WHEN 'penalty_ledger' THEN RETURN jsonb_build_array(j->'entry_id');
