--
-- Name: og70_row_account_restrictions_og_guard_account_restriction(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_account_restrictions_og_guard_account_restriction(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.account_restrictions; OLD og_compat.account_restrictions;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='account_restrictions';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.account_restrictions,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.account_restrictions,coalesce(p_old,'{}'::jsonb));
    PERFORM 1 FROM og_compat.users WHERE user_id=NEW.user_id FOR UPDATE;
    IF NOT (og_has_role(NEW.imposed_by,'KTV') OR og_has_role(NEW.imposed_by,'ADMIN')) THEN
        RAISE EXCEPTION 'Restriction needs KTV/Admin authority' USING ERRCODE='23514';
    END IF;
    IF NEW.scope='LOGIN' AND NEW.closed_at IS NULL AND (
        EXISTS(SELECT 1 FROM og_compat.orders o WHERE NEW.user_id IN (o.buyer_id,o.seller_id)
            AND o.status NOT IN ('COMPLETED','CANCELLED','REFUNDED'))
        OR EXISTS(SELECT 1 FROM og_compat.cases c LEFT JOIN og_compat.orders o USING(order_id)
            WHERE c.state NOT IN ('CLOSED','REJECTED')
                AND NEW.user_id IN (c.created_by,o.buyer_id,o.seller_id))) THEN
        RAISE EXCEPTION 'Open obligations require login access; restrict new transactions instead' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


