--
-- Name: og70_row_case_evidence_og_guard_case_evidence(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_case_evidence_og_guard_case_evidence(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.case_evidence; OLD og_compat.case_evidence;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='case_evidence';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  r og_compat.case_rounds; c og_compat.cases; o og_compat.orders; n INTEGER;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.case_evidence,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.case_evidence,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT r FROM og_compat.case_rounds WHERE round_id=NEW.round_id FOR UPDATE;
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=r.case_id;
    IF r.state<>'OPEN' THEN RAISE EXCEPTION 'Evidence round closed' USING ERRCODE='23514'; END IF;
    NEW.submitted_at:=clock_timestamp();
    IF c.order_id IS NOT NULL THEN
        SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=c.order_id;
        IF NEW.submitted_by NOT IN (o.buyer_id,o.seller_id) AND NOT og_has_role(NEW.submitted_by,'KTV') THEN
            RAISE EXCEPTION 'Evidence author not a party/KTV' USING ERRCODE='23514';
        END IF;
        IF NEW.submitted_by=o.buyer_id AND c.case_type='RETURN'
            AND NEW.submitted_at>o.valid_delivered_at+INTERVAL '3 days' THEN
            RAISE EXCEPTION 'Buyer evidence submission deadline passed' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.submitted_by<>c.created_by AND NOT og_has_role(NEW.submitted_by,'KTV') THEN
        RAISE EXCEPTION 'Private system issue evidence author invalid' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO n FROM og_compat.case_evidence WHERE round_id=NEW.round_id
        AND submitted_by=NEW.submitted_by AND submission_no=NEW.submission_no AND media_type=NEW.media_type;
    IF (NEW.media_type='IMAGE' AND n>=5) OR (NEW.media_type='VIDEO' AND n>=2) THEN
        RAISE EXCEPTION 'Evidence submission media limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


