--
-- Name: og70_row_case_rounds_og_guard_case_round(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_case_rounds_og_guard_case_round(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.case_rounds; OLD og_compat.case_rounds;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='case_rounds';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  c og_compat.cases;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.case_rounds,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.case_rounds,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.case_id FOR UPDATE;
    IF (c.case_type='SYSTEM_ISSUE')<>(NEW.stage='SYSTEM_REVIEW') OR
        (NEW.stage='POST_RETURN_RESOLUTION' AND c.valid_returned_at IS NULL) THEN
        RAISE EXCEPTION 'Case round stage incompatible with case/delivery' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_cases_og_guard_return_case(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_cases_og_guard_return_case(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.cases; OLD og_compat.cases;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='cases';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  o og_compat.orders;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.cases,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.cases,coalesce(p_old,'{}'::jsonb));
    IF NEW.state<>'OPEN' THEN RAISE EXCEPTION 'New case starts open' USING ERRCODE='23514'; END IF;
    IF NEW.case_type='RETURN' AND TG_OP='INSERT' THEN
        SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id FOR UPDATE;
        NEW.created_at:=clock_timestamp();
        IF o.workflow_model<>'UC83' OR NEW.created_by<>o.buyer_id OR NOT o.return_allowed
            OR o.valid_delivered_at IS NULL OR o.early_completed_at IS NOT NULL
            OR NEW.created_at>o.valid_delivered_at+INTERVAL '3 days' THEN
            RAISE EXCEPTION 'Order has no current right to request return' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_cases_og_return_case_money_holds(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_cases_og_return_case_money_holds(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.cases; OLD og_compat.cases;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='cases';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.cases,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.cases,coalesce(p_old,'{}'::jsonb));
    IF NEW.case_type='RETURN' THEN
        INSERT INTO og_compat.money_holds(hold_id,component_id,source_key,reason,case_id)
            SELECT gen_random_uuid(),f.component_id,'RETURN_CASE:'||NEW.case_id,'Return case pending',NEW.case_id FROM og_compat.order_fund_components f WHERE f.order_id=NEW.order_id AND f.component_type IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY') AND NOT EXISTS(SELECT 1 FROM og_compat.money_holds h WHERE h.component_id=f.component_id AND h.source_key='RETURN_CASE:'||NEW.case_id);
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_cases_og_validate_case_state(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_cases_og_validate_case_state(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.cases; OLD og_compat.cases;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='cases';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  c og_compat.cases;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.cases,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.cases,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.case_id;
    IF (c.approved_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.case_decisions d JOIN og_compat.case_rounds r USING(round_id)
        WHERE r.case_id=c.case_id AND d.outcome='APPROVE_RETURN' AND d.is_final))
        OR (c.state IN ('CLOSED','REJECTED') AND NOT EXISTS(SELECT 1 FROM og_compat.case_decisions d JOIN og_compat.case_rounds r USING(round_id)
            WHERE r.case_id=c.case_id AND d.is_final AND d.outcome IN
                ('REJECT_RETURN','FULL_GOODS_REFUND','EXEMPT_GOODS_REFUND','SYSTEM_RESOLVED')))
        OR (c.valid_returned_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.shipments s
            WHERE s.return_case_id=c.case_id AND s.leg='RETURN' AND s.valid_delivery_at=c.valid_returned_at)) THEN
        RAISE EXCEPTION 'Case state requires corresponding decision/delivery proof' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


