--
-- Name: og70_row_checkout_groups_og_guard_checkout_snapshot(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_checkout_groups_og_guard_checkout_snapshot(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.checkout_groups; OLD og_compat.checkout_groups;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='checkout_groups';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.checkout_groups,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.checkout_groups,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME='checkout_groups' THEN
        IF TG_OP='DELETE' OR (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') THEN
            RAISE EXCEPTION 'Checkout command, amount and deadline are immutable' USING ERRCODE='23514'; END IF;
    ELSIF OLD.workflow_model='UC83' AND (TG_OP='DELETE' OR
        ROW(NEW.workflow_model,NEW.group_id,NEW.checkout_group_id,NEW.buyer_id,NEW.seller_id,NEW.subtotal,
            NEW.shipping_fee,NEW.total_amount,NEW.voucher_discount_amount,NEW.shipping_discount_amount,
            NEW.points_discount_amount,NEW.return_allowed,NEW.delivery_method,NEW.carrier_snapshot,NEW.handover_day,
            NEW.payment_due_at,NEW.created_at,NEW.shipping_recipient_name,NEW.shipping_phone_number,NEW.shipping_province,
            NEW.shipping_district,NEW.shipping_ward,NEW.shipping_detail_address)
        IS DISTINCT FROM ROW(OLD.workflow_model,OLD.group_id,OLD.checkout_group_id,OLD.buyer_id,OLD.seller_id,OLD.subtotal,
            OLD.shipping_fee,OLD.total_amount,OLD.voucher_discount_amount,OLD.shipping_discount_amount,
            OLD.points_discount_amount,OLD.return_allowed,OLD.delivery_method,OLD.carrier_snapshot,OLD.handover_day,
            OLD.payment_due_at,OLD.created_at,OLD.shipping_recipient_name,OLD.shipping_phone_number,OLD.shipping_province,
            OLD.shipping_district,OLD.shipping_ward,OLD.shipping_detail_address)) THEN
        RAISE EXCEPTION 'UC83 order checkout snapshot retained' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_checkout_groups_og_validate_checkout_aggregate(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_checkout_groups_og_validate_checkout_aggregate(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.checkout_groups; OLD og_compat.checkout_groups;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='checkout_groups';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  g og_compat.checkout_groups; gid UUID; o og_compat.orders; n INTEGER;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.checkout_groups,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.checkout_groups,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME='checkout_groups' THEN gid:=NEW.group_id;
    ELSIF TG_TABLE_NAME='orders' THEN gid:=NEW.group_id;
    ELSE SELECT group_id INTO gid FROM og_compat.orders WHERE order_id=NEW.order_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    SELECT * INTO STRICT g FROM og_compat.checkout_groups WHERE group_id=gid FOR UPDATE;
    IF g.expected_total<>(SELECT COALESCE(sum(total_amount),0) FROM og_compat.orders WHERE group_id=gid)
       OR NOT EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=gid) THEN
        RAISE EXCEPTION 'Checkout total must equal all orders' USING ERRCODE='23514';
    END IF;
    FOR o IN SELECT * FROM og_compat.orders WHERE group_id=gid LOOP
        IF o.payment_due_at<>g.payment_due_at OR o.delivery_method<>g.delivery_method
            OR o.carrier_snapshot IS DISTINCT FROM g.carrier
            OR jsonb_build_object('recipient_name',o.shipping_recipient_name,'phone_number',o.shipping_phone_number,
                'province',o.shipping_province,'district',o.shipping_district,'ward',o.shipping_ward,
                'detail_address',o.shipping_detail_address)<>g.address_snapshot
            OR o.subtotal<>(SELECT COALESCE(sum(agreed_price*quantity),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR o.voucher_discount_amount<>(SELECT COALESCE(sum(voucher_allocation),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR o.points_discount_amount<>(SELECT COALESCE(sum(points_allocation),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR EXISTS(SELECT 1 FROM og_compat.order_items i WHERE i.order_id=o.order_id AND NOT EXISTS(
                SELECT 1 FROM og_compat.inventory_reservations r WHERE r.order_item_id=i.order_item_id AND r.quantity=i.quantity)) THEN
            RAISE EXCEPTION 'Checkout snapshots/items/reservations incomplete' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_checkout_groups_og_validate_discount_totals(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_checkout_groups_og_validate_discount_totals(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.checkout_groups; OLD og_compat.checkout_groups;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='checkout_groups';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  gid UUID; v NUMERIC; p NUMERIC;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.checkout_groups,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.checkout_groups,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME IN ('checkout_groups','orders','checkout_redemptions','reward_ledger') THEN gid:=NEW.group_id;
    ELSE SELECT o.group_id INTO gid FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id) WHERE i.order_item_id=NEW.order_item_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    PERFORM 1 FROM og_compat.checkout_groups WHERE group_id=gid FOR UPDATE;
    SELECT COALESCE(sum(voucher_discount_amount+shipping_discount_amount),0),COALESCE(sum(points_discount_amount),0)
        INTO v,p FROM og_compat.orders WHERE group_id=gid;
    IF v<>COALESCE((SELECT discount_amount FROM og_compat.checkout_redemptions WHERE group_id=gid),0)
        OR p<>COALESCE((SELECT -l.points_delta*r.point_value FROM og_compat.reward_ledger l JOIN og_compat.reward_policies r USING(policy_id)
            WHERE l.group_id=gid AND l.entry_type='DEBIT_CHECKOUT'),0)
        OR EXISTS(SELECT 1 FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id) WHERE o.group_id=gid AND (
            i.voucher_allocation<>(SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations d WHERE d.order_item_id=i.order_item_id
                AND redemption_id IS NOT NULL AND component='GOODS')
            OR i.points_allocation<>(SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations d WHERE d.order_item_id=i.order_item_id
                AND reward_entry_id IS NOT NULL)))
        OR EXISTS(SELECT 1 FROM og_compat.orders o WHERE o.group_id=gid AND o.shipping_discount_amount<>(
            SELECT COALESCE(sum(d.amount),0) FROM og_compat.discount_allocations d JOIN og_compat.order_items i USING(order_item_id)
            WHERE i.order_id=o.order_id AND d.component='SHIPPING'))
        OR EXISTS(SELECT 1 FROM og_compat.checkout_redemptions c WHERE c.group_id=gid AND c.discount_amount<>(
            SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations WHERE redemption_id=c.redemption_id)) THEN
        RAISE EXCEPTION 'Voucher/points allocations must exactly conserve checkout discounts' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_checkout_redemptions_og_redeem_voucher(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_checkout_redemptions_og_redeem_voucher(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.checkout_redemptions; OLD og_compat.checkout_redemptions;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='checkout_redemptions';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  v og_compat.voucher_grants; r og_compat.voucher_revisions; base NUMERIC; benefit NUMERIC;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.checkout_redemptions,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.checkout_redemptions,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT v FROM og_compat.voucher_grants WHERE grant_id=NEW.grant_id FOR UPDATE;
    SELECT * INTO STRICT r FROM og_compat.voucher_revisions WHERE revision_id=v.revision_id FOR UPDATE;
    IF v.state<>'AVAILABLE' OR v.expires_at<=NEW.redeemed_at THEN
        RAISE EXCEPTION 'Voucher already used/revoked/expired' USING ERRCODE='23514';
    END IF;
    IF r.benefit_component='GOODS' THEN
        SELECT COALESCE(sum(i.agreed_price*i.quantity),0) INTO base FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id)
            WHERE o.group_id=NEW.group_id AND (r.scope='CHECKOUT' OR EXISTS(SELECT 1 FROM og_compat.voucher_revision_products
                WHERE revision_id=r.revision_id AND product_id=i.product_id));
    ELSE SELECT COALESCE(sum(shipping_fee),0) INTO base FROM og_compat.orders WHERE group_id=NEW.group_id; END IF;
    benefit:=LEAST(base,CASE WHEN r.discount_type='FIXED_AMOUNT' THEN r.discount_value
        ELSE round(base*r.discount_value/100,0) END,COALESCE(r.max_discount_amount,base));
    IF base<r.min_eligible_amount OR NEW.discount_amount<>benefit OR EXISTS(
        SELECT 1 FROM og_compat.voucher_revision_revocations WHERE revision_id=r.revision_id) THEN
        RAISE EXCEPTION 'Voucher amount/minimum/revocation differs from immutable policy' USING ERRCODE='23514'; END IF;
    NEW.policy_snapshot:=r.policy_snapshot||jsonb_build_object('benefit_component',r.benefit_component,
        'discount_type',r.discount_type,'discount_value',r.discount_value,'max_discount_amount',r.max_discount_amount,
        'min_eligible_amount',r.min_eligible_amount,'scope',r.scope);
    UPDATE og_compat.voucher_grants SET state='REDEEMED' WHERE grant_id=v.grant_id;
    RETURN to_jsonb(NEW);
END;
$$;


