--
-- Name: og70_row_ekyc_decisions_og_apply_ekyc_decision(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_ekyc_decisions_og_apply_ekyc_decision(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.ekyc_decisions; OLD og_compat.ekyc_decisions;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='ekyc_decisions';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  p og_compat.ekyc_profiles;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.ekyc_decisions,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.ekyc_decisions,coalesce(p_old,'{}'::jsonb));
    NEW.decided_at:=clock_timestamp();
    SELECT * INTO STRICT p FROM og_compat.ekyc_profiles WHERE profile_id=NEW.profile_id FOR UPDATE;
    IF p.state<>'PENDING' OR NOT og_has_role(NEW.reviewed_by,'KTV') THEN
        RAISE EXCEPTION 'Only KTV can decide a pending eKYC revision' USING ERRCODE='23514';
    END IF;
    IF NEW.outcome='VERIFIED' AND (
        p.document_digest IS NULL
        OR (SELECT count(DISTINCT asset_type) FROM og_compat.ekyc_private_assets
            WHERE profile_id=p.profile_id AND deleted_at IS NULL AND expires_at>NEW.decided_at
              AND asset_type IN ('CARD_FRONT','CARD_BACK','LIVE_FRAME','REFERENCE')) <> 4) THEN
        RAISE EXCEPTION 'eKYC identity/private evidence incomplete' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.ekyc_profiles SET state=NEW.outcome,
        verified_at=CASE WHEN NEW.outcome='VERIFIED' THEN NEW.decided_at END,
        reference_expires_at=CASE WHEN NEW.outcome='VERIFIED' THEN
            LEAST(NEW.decided_at+INTERVAL '3 months',
                (SELECT min(expires_at) FROM og_compat.ekyc_private_assets WHERE profile_id=p.profile_id AND deleted_at IS NULL)) END,
        version=version+1 WHERE profile_id=p.profile_id;
    RETURN to_jsonb(NEW);
END;
$$;


