--
-- Name: og70_row_ekyc_private_assets_og_guard_private_asset(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_ekyc_private_assets_og_guard_private_asset(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.ekyc_private_assets; OLD og_compat.ekyc_private_assets;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='ekyc_private_assets';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.ekyc_private_assets,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.ekyc_private_assets,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND ROW(NEW.profile_id,NEW.asset_type,NEW.object_key,
        NEW.content_digest,NEW.captured_at,NEW.expires_at) IS DISTINCT FROM
        ROW(OLD.profile_id,OLD.asset_type,OLD.object_key,OLD.content_digest,OLD.captured_at,OLD.expires_at)) THEN
        RAISE EXCEPTION 'Private evidence identity retained; mark deletion only' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles WHERE profile_id=NEW.profile_id
        AND state IN ('DRAFT','IN_PROGRESS')) THEN
        RAISE EXCEPTION 'Only open eKYC accepts new evidence' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_ekyc_profiles_og_guard_ekyc_snapshot(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_ekyc_profiles_og_guard_ekyc_snapshot(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.ekyc_profiles; OLD og_compat.ekyc_profiles;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='ekyc_profiles';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.ekyc_profiles,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.ekyc_profiles,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (
        ROW(NEW.profile_id,NEW.user_id,NEW.revision_no,NEW.created_at) IS DISTINCT FROM
        ROW(OLD.profile_id,OLD.user_id,OLD.revision_no,OLD.created_at)
        OR (OLD.state IN ('PENDING','VERIFIED','REJECTED','EXPIRED') AND
            ROW(NEW.submitted_data,NEW.ai_summary,NEW.document_digest,NEW.submitted_at) IS DISTINCT FROM
            ROW(OLD.submitted_data,OLD.ai_summary,OLD.document_digest,OLD.submitted_at))
        OR (OLD.state IN ('VERIFIED','REJECTED','EXPIRED') AND NEW.state<>OLD.state
            AND NOT (OLD.state='VERIFIED' AND NEW.state='EXPIRED')))) THEN
        RAISE EXCEPTION 'eKYC identity/submitted evidence is immutable' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_ekyc_profiles_og_validate_identity_decision(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_ekyc_profiles_og_validate_identity_decision(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.ekyc_profiles; OLD og_compat.ekyc_profiles;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='ekyc_profiles';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.ekyc_profiles,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.ekyc_profiles,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME='ekyc_profiles' THEN
        IF EXISTS(SELECT 1 FROM og_compat.ekyc_profiles p WHERE p.profile_id=NEW.profile_id
            AND p.state IN ('VERIFIED','REJECTED') AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_decisions d
                WHERE d.profile_id=p.profile_id AND d.outcome=p.state)) THEN
            RAISE EXCEPTION 'Final eKYC state requires KTV decision' USING ERRCODE='23514';
        END IF;
    ELSE
        IF EXISTS(SELECT 1 FROM og_compat.seller_profiles p WHERE p.seller_profile_id=NEW.seller_profile_id
            AND p.state IN ('APPROVED','REJECTED') AND NOT EXISTS(SELECT 1 FROM og_compat.seller_profile_decisions d
                WHERE d.seller_profile_id=p.seller_profile_id AND d.revision_no=p.revision_no AND d.outcome=p.state)) THEN
            RAISE EXCEPTION 'Final seller state requires KTV decision' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_ekyc_verification_attempts_og_guard_ekyc_attempt(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_ekyc_verification_attempts_og_guard_ekyc_attempt(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.ekyc_verification_attempts; OLD og_compat.ekyc_verification_attempts;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='ekyc_verification_attempts';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  p og_compat.ekyc_profiles;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.ekyc_verification_attempts,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.ekyc_verification_attempts,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT p FROM og_compat.ekyc_profiles WHERE profile_id=NEW.profile_id FOR UPDATE;
    IF p.state NOT IN ('DRAFT','IN_PROGRESS') THEN
        RAISE EXCEPTION 'eKYC input is closed' USING ERRCODE='23514';
    END IF;
    NEW.attempted_at := clock_timestamp();
    IF NEW.result='MANUAL_REVIEW' AND NOT og_has_role(NEW.fallback_authorized_by,'ADMIN') THEN
        RAISE EXCEPTION 'Manual fallback requires Admin' USING ERRCODE='23514';
    END IF;
    IF NEW.result='NON_MATCH' THEN
        IF p.nonmatch_count >= 15 OR
           (p.last_nonmatch_at IS NOT NULL AND NEW.attempted_at < p.last_nonmatch_at + INTERVAL '3 seconds') THEN
            RAISE EXCEPTION 'eKYC attempt limit/cooldown' USING ERRCODE='23514';
        END IF;
        UPDATE og_compat.ekyc_profiles SET nonmatch_count=nonmatch_count+1,last_nonmatch_at=NEW.attempted_at
            WHERE profile_id=p.profile_id;
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


