--
-- Name: og70_row_handover_confirmations_og_guard_handover_party(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_handover_confirmations_og_guard_handover_party(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.handover_confirmations; OLD og_compat.handover_confirmations;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='handover_confirmations';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.handover_confirmations,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.handover_confirmations,coalesce(p_old,'{}'::jsonb));
    IF NOT EXISTS(SELECT 1 FROM og_compat.shipments s JOIN og_compat.orders o USING(order_id)
        WHERE s.shipment_id=NEW.shipment_id AND s.workflow_model='UC83'
          AND s.delivery_method IN ('SELF_PICKUP','SELF_DELIVERY')
          AND NEW.user_id=CASE NEW.party WHEN 'BUYER' THEN o.buyer_id ELSE o.seller_id END) THEN
        RAISE EXCEPTION 'Handover confirmation must belong to correct order party' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


