--
-- Name: og70_row_inventory_reservations_og_guard_inventor_032f6f7f26(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_inventory_reservations_og_guard_inventor_032f6f7f26(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.inventory_reservations; OLD og_compat.inventory_reservations;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='inventory_reservations';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  p og_compat.products; o og_compat.orders; i og_compat.order_items; delta INTEGER;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.inventory_reservations,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.inventory_reservations,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reservation history is retained' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT p FROM og_compat.products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT * INTO STRICT i FROM og_compat.order_items WHERE order_item_id=NEW.order_item_id;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=i.order_id;
    IF p.workflow_model<>'UC83' OR i.workflow_model<>'UC83' OR o.workflow_model<>'UC83'
       OR NEW.quantity<>i.quantity OR NEW.expires_at<>o.payment_due_at THEN
        RAISE EXCEPTION 'Reservation must match UC83 item and original deadline' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'HELD' OR p.status<>'ACTIVE' OR p.public_revision_id IS DISTINCT FROM i.product_revision_id OR p.quantity_available<NEW.quantity
           OR p.deleted_at IS NOT NULL OR clock_timestamp()>=NEW.expires_at THEN
            RAISE EXCEPTION 'Product quantity unavailable' USING ERRCODE='23514';
        END IF;
        UPDATE og_compat.products SET quantity_held=quantity_held+NEW.quantity WHERE product_id=p.product_id;
    ELSE
        IF ROW(NEW.product_id,NEW.order_item_id,NEW.quantity,NEW.created_at,NEW.expires_at,NEW.command_key)
           IS DISTINCT FROM ROW(OLD.product_id,OLD.order_item_id,OLD.quantity,OLD.created_at,OLD.expires_at,OLD.command_key) THEN
            RAISE EXCEPTION 'Reservation snapshot is immutable' USING ERRCODE='23514';
        END IF;
        IF NEW.state=OLD.state THEN RETURN to_jsonb(NEW); END IF;
        IF NOT ((OLD.state='HELD' AND NEW.state IN ('FUNDED','RELEASED'))
            OR (OLD.state='FUNDED' AND NEW.state IN ('CONSUMED','RELEASED'))) THEN
            RAISE EXCEPTION 'Invalid reservation transition' USING ERRCODE='23514';
        END IF;
        IF NEW.state='FUNDED' AND (o.paid_confirmed_at IS NULL OR o.paid_confirmed_at>OLD.expires_at
            OR o.status='CANCELLED') THEN
            RAISE EXCEPTION 'Late payment cannot fund cancelled/expired reservation' USING ERRCODE='23514';
        END IF;
        IF NEW.state='CONSUMED' AND (o.status<>'SELLER_CONFIRMED' OR o.seller_accept_due_at IS NULL
            OR clock_timestamp()>o.seller_accept_due_at) THEN
            RAISE EXCEPTION 'Seller acceptance is not eligible' USING ERRCODE='23514';
        END IF;
        IF NEW.state IN ('RELEASED','CONSUMED') THEN
            delta := CASE WHEN NEW.state='CONSUMED' THEN NEW.quantity ELSE 0 END;
            UPDATE og_compat.products SET quantity_held=quantity_held-NEW.quantity,quantity_sold=quantity_sold+delta,
                status=CASE WHEN quantity_sold+delta=quantity_total THEN 'SOLD' ELSE status END
                WHERE product_id=p.product_id;
        END IF;
        NEW.changed_at:=clock_timestamp();
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_inventory_reservations_og_guard_new_transaction(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_inventory_reservations_og_guard_new_transaction(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.inventory_reservations; OLD og_compat.inventory_reservations;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='inventory_reservations';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  o og_compat.orders;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.inventory_reservations,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.inventory_reservations,coalesce(p_old,'{}'::jsonb));
    SELECT o1.* INTO STRICT o FROM og_compat.order_items i JOIN og_compat.orders o1 USING(order_id) WHERE i.order_item_id=NEW.order_item_id;
    PERFORM 1 FROM og_compat.users WHERE user_id IN (o.buyer_id,o.seller_id) ORDER BY user_id FOR UPDATE;
    IF NOT og_has_role(o.buyer_id,'BUYER') OR NOT og_has_role(o.seller_id,'SELLER')
        OR EXISTS(SELECT 1 FROM og_compat.account_restrictions WHERE user_id IN (o.buyer_id,o.seller_id) AND closed_at IS NULL)
        OR EXISTS(SELECT 1 FROM og_compat.seller_buyer_blocks WHERE seller_id=o.seller_id AND buyer_id=o.buyer_id AND unblocked_at IS NULL)
        OR NOT EXISTS(SELECT 1 FROM og_compat.seller_profiles s JOIN og_compat.ekyc_profiles e ON e.profile_id=s.ekyc_profile_id
            JOIN og_compat.ekyc_decisions d ON d.profile_id=e.profile_id WHERE s.user_id=o.seller_id AND s.state='APPROVED'
                AND e.state='VERIFIED' AND d.outcome='VERIFIED' AND e.reference_expires_at>clock_timestamp())
        OR EXISTS(SELECT 1 FROM og_compat.ekyc_profiles WHERE user_id=o.seller_id AND state IN ('DRAFT','IN_PROGRESS','PENDING')) THEN
        RAISE EXCEPTION 'New transaction blocked by identity/restriction/party block' USING ERRCODE='23514'; END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_listing_fee_assessments_og_compute_listi_7358e0ac72(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_listing_fee_assessments_og_compute_listi_7358e0ac72(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.listing_fee_assessments; OLD og_compat.listing_fee_assessments;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='listing_fee_assessments';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  r og_compat.product_revisions; f og_compat.listing_fee_policies;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.listing_fee_assessments,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.listing_fee_assessments,coalesce(p_old,'{}'::jsonb));
    PERFORM 1 FROM og_compat.products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT * INTO STRICT r FROM og_compat.product_revisions WHERE revision_id=NEW.revision_id;
    IF r.state<>'SUBMITTED' OR r.provenance<>'UC83' OR NOT EXISTS (
        SELECT 1 FROM og_compat.product_moderation_decisions WHERE decision_id=NEW.decision_id
            AND revision_id=r.revision_id AND decision='APPROVED') THEN
        RAISE EXCEPTION 'Fee requires approval of this revision' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM og_compat.listing_fee_charges c JOIN og_compat.listing_fee_assessments a USING(assessment_id)
              WHERE a.product_id=NEW.product_id AND c.state IN ('PENDING','RECONCILIATION')) THEN
        RAISE EXCEPTION 'Listing has an unresolved fee charge' USING ERRCODE='23514';
    END IF;
    NEW.assessed_at := clock_timestamp();
    SELECT * INTO STRICT f FROM og_compat.listing_fee_policies WHERE policy_id=NEW.policy_id
        AND effective_from<=NEW.assessed_at AND (effective_until IS NULL OR effective_until>NEW.assessed_at);
    NEW.listed_total := r.listed_unit_price*r.quantity;
    SELECT listed_total INTO NEW.previous_approved_total FROM og_compat.listing_fee_assessments
        WHERE product_id=NEW.product_id ORDER BY assessment_id DESC LIMIT 1;
    SELECT COALESCE(sum(receipt.amount),0) INTO NEW.cumulative_before FROM og_compat.listing_fee_receipts receipt
        JOIN og_compat.listing_fee_charges c USING(charge_id) JOIN og_compat.listing_fee_assessments a USING(assessment_id)
        WHERE a.product_id=NEW.product_id;
    NEW.computed_fee := CASE WHEN NEW.listed_total<f.threshold_amount THEN f.fixed_below
        ELSE round(NEW.listed_total*f.rate_at_or_above,0) END;
    NEW.amount_due := CASE WHEN NEW.previous_approved_total IS NULL
        OR NEW.listed_total>NEW.previous_approved_total
        THEN greatest(0,NEW.computed_fee-NEW.cumulative_before) ELSE 0 END;
    RETURN to_jsonb(NEW);
END;
$$;


