--

CREATE FUNCTION public.og70_row_listing_fee_charges_og_guard_listing_charge(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.listing_fee_charges; OLD og_compat.listing_fee_charges;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='listing_fee_charges';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.listing_fee_charges,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.listing_fee_charges,coalesce(p_old,'{}'::jsonb));
    IF NOT EXISTS(SELECT 1 FROM og_compat.listing_fee_assessments WHERE assessment_id=NEW.assessment_id
        AND amount_due=NEW.amount AND amount_due>0) THEN
        RAISE EXCEPTION 'Listing fee charge must equal positive assessment due' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND (NEW.assessment_id<>OLD.assessment_id OR NEW.amount<>OLD.amount
        OR (OLD.state='CONFIRMED' AND NEW IS DISTINCT FROM OLD)) THEN
        RAISE EXCEPTION 'Confirmed listing charge is immutable' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


