-- Name: og70_row_listing_fee_policies_og_guard_fee_policy(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_listing_fee_policies_og_guard_fee_policy(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.listing_fee_policies; OLD og_compat.listing_fee_policies;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='listing_fee_policies';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.listing_fee_policies,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.listing_fee_policies,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' OR ROW(NEW.policy_code,NEW.threshold_amount,NEW.fixed_below,NEW.rate_at_or_above,
        NEW.effective_from,NEW.created_by) IS DISTINCT FROM ROW(OLD.policy_code,OLD.threshold_amount,
        OLD.fixed_below,OLD.rate_at_or_above,OLD.effective_from,OLD.created_by)
        OR NEW.effective_until IS NULL OR NEW.effective_until<=clock_timestamp()
        OR EXISTS(SELECT 1 FROM og_compat.listing_fee_assessments WHERE policy_id=OLD.policy_id AND assessed_at>=NEW.effective_until) THEN
        RAISE EXCEPTION 'Keep fee policy history; end policy in the future and create a successor' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_listing_fee_receipts_og_confirm_listing_receipt(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_listing_fee_receipts_og_confirm_listing_receipt(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.listing_fee_receipts; OLD og_compat.listing_fee_receipts;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='listing_fee_receipts';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  c og_compat.listing_fee_charges; p BIGINT;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.listing_fee_receipts,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.listing_fee_receipts,coalesce(p_old,'{}'::jsonb));
    SELECT product_id INTO STRICT p FROM og_compat.listing_fee_assessments a JOIN og_compat.listing_fee_charges ch USING(assessment_id)
        WHERE ch.charge_id=NEW.charge_id;
    PERFORM 1 FROM og_compat.products WHERE product_id=p FOR UPDATE;
    SELECT * INTO STRICT c FROM og_compat.listing_fee_charges WHERE charge_id=NEW.charge_id FOR UPDATE;
    IF c.state<>'PENDING' OR NEW.amount<>c.amount THEN
        RAISE EXCEPTION 'Listing fee amount/state mismatch; reconciliation required' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.listing_fee_charges SET state='CONFIRMED' WHERE charge_id=NEW.charge_id;
    RETURN to_jsonb(NEW);
END;
$$;


