--
-- Name: og70_row_notifications_og_guard_manual_recipient(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_notifications_og_guard_manual_recipient(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.notifications; OLD og_compat.notifications;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='notifications';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  d og_compat.notification_dispatches;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.notifications,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.notifications,coalesce(p_old,'{}'::jsonb));
    IF NEW.dispatch_id IS NOT NULL THEN
        SELECT * INTO STRICT d FROM og_compat.notification_dispatches WHERE dispatch_id=NEW.dispatch_id;
        IF NOT (og_has_role(NEW.user_id,'BUYER') OR og_has_role(NEW.user_id,'SELLER') OR og_has_role(NEW.user_id,'KTV')) THEN
            RAISE EXCEPTION 'Manual recipient must be Buyer/Seller/KTV' USING ERRCODE='23514';
        END IF;
        NEW.sender_id:=d.sender_id; NEW.event_id:=d.event_id; NEW.title:=d.title; NEW.content:=d.content;
        NEW.target_data:=d.target_data;
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


