--
-- Name: og70_row_order_fund_components_og_guard_fund_component(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_order_fund_components_og_guard_fund_component(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.order_fund_components; OLD og_compat.order_fund_components;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='order_fund_components';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  o og_compat.orders; expected NUMERIC;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.order_fund_components,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.order_fund_components,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Fund component history retained' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF ROW(NEW.component_id,NEW.order_id,NEW.allocation_id,NEW.late_confirmation_id,NEW.component_type,
            NEW.confirmed_amount,NEW.funding_reference,NEW.confirmed_at) IS DISTINCT FROM
            ROW(OLD.component_id,OLD.order_id,OLD.allocation_id,OLD.late_confirmation_id,OLD.component_type,
            OLD.confirmed_amount,OLD.funding_reference,OLD.confirmed_at) OR p_depth<2 THEN
            RAISE EXCEPTION 'Money amount/source immutable; balances change through operations only' USING ERRCODE='23514';
        END IF;
        RETURN to_jsonb(NEW);
    END IF;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id FOR UPDATE;
    expected:=CASE NEW.component_type
        WHEN 'GOODS_CASH' THEN o.subtotal-o.voucher_discount_amount-o.points_discount_amount
        WHEN 'SHIPPING_CASH' THEN o.shipping_fee-o.shipping_discount_amount
        WHEN 'PLATFORM_GOODS_SUBSIDY' THEN o.voucher_discount_amount+o.points_discount_amount
        WHEN 'PLATFORM_SHIPPING_SUBSIDY' THEN o.shipping_discount_amount
        WHEN 'LATE_PAYMENT_CASH' THEN o.total_amount END;
    IF o.workflow_model<>'UC83' OR NEW.confirmed_amount<>expected
        OR NEW.reserved_amount<>0 OR NEW.refunded_amount<>0 OR NEW.released_amount<>0 OR NEW.version<>0
        OR (NEW.component_type='LATE_PAYMENT_CASH' AND NOT EXISTS(
            SELECT 1 FROM og_compat.payment_confirmations c JOIN og_compat.payment_intents i USING(intent_id)
            WHERE c.confirmation_id=NEW.late_confirmation_id AND c.disposition='RECONCILIATION'
                AND i.group_id=o.group_id))
        OR (NEW.component_type LIKE 'PLATFORM_%' AND o.total_amount>0 AND NOT EXISTS(
            SELECT 1 FROM og_compat.payment_allocations WHERE order_id=o.order_id)) THEN
        RAISE EXCEPTION 'Fund component must equal its confirmed order source' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_order_fund_components_og_hold_new_case_component(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_order_fund_components_og_hold_new_case_component(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.order_fund_components; OLD og_compat.order_fund_components;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='order_fund_components';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.order_fund_components,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.order_fund_components,coalesce(p_old,'{}'::jsonb));
    IF NEW.component_type IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY') THEN
        INSERT INTO og_compat.money_holds(hold_id,component_id,source_key,reason,case_id)
            SELECT gen_random_uuid(),NEW.component_id,'RETURN_CASE:'||case_id,'Return case pending',case_id
            FROM og_compat.cases WHERE order_id=NEW.order_id AND case_type='RETURN' AND state NOT IN ('CLOSED','REJECTED');
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_order_items_og_guard_checkout_item(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_order_items_og_guard_checkout_item(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.order_items; OLD og_compat.order_items;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='order_items';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  o og_compat.orders; p og_compat.products; r og_compat.product_revisions;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.order_items,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.order_items,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' THEN
        IF OLD.workflow_model='UC83' THEN RAISE EXCEPTION 'Order item history retained' USING ERRCODE='23514'; END IF;
        RETURN to_jsonb(OLD);
    END IF;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id;
    IF NEW.workflow_model<>o.workflow_model THEN RAISE EXCEPTION 'Item workflow mismatch' USING ERRCODE='23514'; END IF;
    IF NEW.workflow_model='UC83' THEN
        SELECT * INTO STRICT p FROM og_compat.products WHERE product_id=NEW.product_id;
        SELECT * INTO STRICT r FROM og_compat.product_revisions WHERE revision_id=NEW.product_revision_id;
        IF p.seller_id<>o.seller_id OR NEW.return_allowed IS DISTINCT FROM o.return_allowed
           OR NEW.return_allowed IS DISTINCT FROM r.return_allowed OR NEW.listed_price<>r.listed_unit_price
           OR NOT (r.delivery_options ? o.delivery_method) THEN
            RAISE EXCEPTION 'Seller/return/delivery/price snapshot mismatch' USING ERRCODE='23514';
        END IF;
        IF NEW.accepted_offer_id IS NOT NULL AND NOT EXISTS(
            SELECT 1 FROM og_compat.offers offer JOIN og_compat.conversations c USING(conversation_id)
            WHERE offer.offer_id=NEW.accepted_offer_id AND offer.status='ACCEPTED'
              AND c.buyer_id=o.buyer_id AND c.seller_id=o.seller_id AND c.product_id=NEW.product_id
              AND offer.offered_item_price=NEW.agreed_price) THEN
            RAISE EXCEPTION 'Accepted offer belongs to another transaction' USING ERRCODE='23514';
        END IF;
        IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'UC83 order item snapshot is immutable' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_order_items_og_validate_checkout_aggregate(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_order_items_og_validate_checkout_aggregate(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.order_items; OLD og_compat.order_items;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='order_items';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  g og_compat.checkout_groups; gid UUID; o og_compat.orders; n INTEGER;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.order_items,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.order_items,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME='checkout_groups' THEN gid:=NEW.group_id;
    ELSIF TG_TABLE_NAME='orders' THEN gid:=NEW.group_id;
    ELSE SELECT group_id INTO gid FROM og_compat.orders WHERE order_id=NEW.order_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    SELECT * INTO STRICT g FROM og_compat.checkout_groups WHERE group_id=gid FOR UPDATE;
    IF g.expected_total<>(SELECT COALESCE(sum(total_amount),0) FROM og_compat.orders WHERE group_id=gid)
       OR NOT EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=gid) THEN
        RAISE EXCEPTION 'Checkout total must equal all orders' USING ERRCODE='23514';
    END IF;
    FOR o IN SELECT * FROM og_compat.orders WHERE group_id=gid LOOP
        IF o.payment_due_at<>g.payment_due_at OR o.delivery_method<>g.delivery_method
            OR o.carrier_snapshot IS DISTINCT FROM g.carrier
            OR jsonb_build_object('recipient_name',o.shipping_recipient_name,'phone_number',o.shipping_phone_number,
                'province',o.shipping_province,'district',o.shipping_district,'ward',o.shipping_ward,
                'detail_address',o.shipping_detail_address)<>g.address_snapshot
            OR o.subtotal<>(SELECT COALESCE(sum(agreed_price*quantity),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR o.voucher_discount_amount<>(SELECT COALESCE(sum(voucher_allocation),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR o.points_discount_amount<>(SELECT COALESCE(sum(points_allocation),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR EXISTS(SELECT 1 FROM og_compat.order_items i WHERE i.order_id=o.order_id AND NOT EXISTS(
                SELECT 1 FROM og_compat.inventory_reservations r WHERE r.order_item_id=i.order_item_id AND r.quantity=i.quantity)) THEN
            RAISE EXCEPTION 'Checkout snapshots/items/reservations incomplete' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_order_items_og_validate_discount_totals(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_order_items_og_validate_discount_totals(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.order_items; OLD og_compat.order_items;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='order_items';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  gid UUID; v NUMERIC; p NUMERIC;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.order_items,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.order_items,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME IN ('checkout_groups','orders','checkout_redemptions','reward_ledger') THEN gid:=NEW.group_id;
    ELSE SELECT o.group_id INTO gid FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id) WHERE i.order_item_id=NEW.order_item_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    PERFORM 1 FROM og_compat.checkout_groups WHERE group_id=gid FOR UPDATE;
    SELECT COALESCE(sum(voucher_discount_amount+shipping_discount_amount),0),COALESCE(sum(points_discount_amount),0)
        INTO v,p FROM og_compat.orders WHERE group_id=gid;
    IF v<>COALESCE((SELECT discount_amount FROM og_compat.checkout_redemptions WHERE group_id=gid),0)
        OR p<>COALESCE((SELECT -l.points_delta*r.point_value FROM og_compat.reward_ledger l JOIN og_compat.reward_policies r USING(policy_id)
            WHERE l.group_id=gid AND l.entry_type='DEBIT_CHECKOUT'),0)
        OR EXISTS(SELECT 1 FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id) WHERE o.group_id=gid AND (
            i.voucher_allocation<>(SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations d WHERE d.order_item_id=i.order_item_id
                AND redemption_id IS NOT NULL AND component='GOODS')
            OR i.points_allocation<>(SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations d WHERE d.order_item_id=i.order_item_id
                AND reward_entry_id IS NOT NULL)))
        OR EXISTS(SELECT 1 FROM og_compat.orders o WHERE o.group_id=gid AND o.shipping_discount_amount<>(
            SELECT COALESCE(sum(d.amount),0) FROM og_compat.discount_allocations d JOIN og_compat.order_items i USING(order_item_id)
            WHERE i.order_id=o.order_id AND d.component='SHIPPING'))
        OR EXISTS(SELECT 1 FROM og_compat.checkout_redemptions c WHERE c.group_id=gid AND c.discount_amount<>(
            SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations WHERE redemption_id=c.redemption_id)) THEN
        RAISE EXCEPTION 'Voucher/points allocations must exactly conserve checkout discounts' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_orders_og_guard_checkout_snapshot(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_orders_og_guard_checkout_snapshot(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.orders; OLD og_compat.orders;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='orders';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.orders,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.orders,coalesce(p_old,'{}'::jsonb));
    IF TG_TABLE_NAME='checkout_groups' THEN
        IF TG_OP='DELETE' OR (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') THEN
            RAISE EXCEPTION 'Checkout command, amount and deadline are immutable' USING ERRCODE='23514'; END IF;
    ELSIF OLD.workflow_model='UC83' AND (TG_OP='DELETE' OR
        ROW(NEW.workflow_model,NEW.group_id,NEW.checkout_group_id,NEW.buyer_id,NEW.seller_id,NEW.subtotal,
            NEW.shipping_fee,NEW.total_amount,NEW.voucher_discount_amount,NEW.shipping_discount_amount,
            NEW.points_discount_amount,NEW.return_allowed,NEW.delivery_method,NEW.carrier_snapshot,NEW.handover_day,
            NEW.payment_due_at,NEW.created_at,NEW.shipping_recipient_name,NEW.shipping_phone_number,NEW.shipping_province,
            NEW.shipping_district,NEW.shipping_ward,NEW.shipping_detail_address)
        IS DISTINCT FROM ROW(OLD.workflow_model,OLD.group_id,OLD.checkout_group_id,OLD.buyer_id,OLD.seller_id,OLD.subtotal,
            OLD.shipping_fee,OLD.total_amount,OLD.voucher_discount_amount,OLD.shipping_discount_amount,
            OLD.points_discount_amount,OLD.return_allowed,OLD.delivery_method,OLD.carrier_snapshot,OLD.handover_day,
            OLD.payment_due_at,OLD.created_at,OLD.shipping_recipient_name,OLD.shipping_phone_number,OLD.shipping_province,
            OLD.shipping_district,OLD.shipping_ward,OLD.shipping_detail_address)) THEN
        RAISE EXCEPTION 'UC83 order checkout snapshot retained' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


