--
-- Name: og70_row_orders_og_validate_order_workflow_proof(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_orders_og_validate_order_workflow_proof(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.orders; OLD og_compat.orders;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='orders';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  o og_compat.orders;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.orders,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.orders,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id;
    IF o.workflow_model='UC83' AND (
        (o.paid_confirmed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.payment_allocations a
            JOIN og_compat.payment_confirmations c USING(confirmation_id) WHERE a.order_id=o.order_id
                AND c.disposition='ALLOCATABLE' AND c.confirmed_at=o.paid_confirmed_at)
            AND NOT (o.total_amount=0 AND EXISTS(SELECT 1 FROM og_compat.zero_checkout_confirmations z
                WHERE z.group_id=o.group_id AND z.buyer_id=o.buyer_id AND z.confirmed_at=o.paid_confirmed_at)))
        OR (o.valid_delivered_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.shipments s WHERE s.order_id=o.order_id
            AND s.leg='OUTBOUND' AND s.valid_delivery_at=o.valid_delivered_at))
        OR (o.early_completed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.order_events e WHERE e.order_id=o.order_id
            AND e.actor_id=o.buyer_id AND e.event_type='EARLY_COMPLETION_ACCEPTED'))
        OR (o.seller_accept_due_at IS NOT NULL AND o.seller_accept_due_at<>
            COALESCE(o.paid_confirmed_at,o.created_at)+INTERVAL '2 days')) THEN
        RAISE EXCEPTION 'Order deadlines/payment/delivery/consent need source proof' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$$;


