--
-- Name: og70_row_payment_allocations_og_guard_payment_allocation(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_payment_allocations_og_guard_payment_allocation(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.payment_allocations; OLD og_compat.payment_allocations;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='payment_allocations';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.payment_allocations,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.payment_allocations,coalesce(p_old,'{}'::jsonb));
    PERFORM 1 FROM og_compat.payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF NOT EXISTS(SELECT 1 FROM og_compat.payment_intents i JOIN og_compat.payment_confirmations c USING(intent_id)
        JOIN og_compat.orders o ON o.group_id=i.group_id WHERE i.intent_id=NEW.intent_id AND i.purpose='CHECKOUT_GROUP'
          AND c.confirmation_id=NEW.confirmation_id AND c.disposition='ALLOCATABLE'
          AND o.order_id=NEW.order_id AND o.total_amount=NEW.amount AND o.status='PAYMENT_PENDING') THEN
        RAISE EXCEPTION 'Allocation does not belong to eligible order/confirmed group' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


