--
-- Name: og70_row_payment_confirmations_og_validate_paymen_f535678725(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_payment_confirmations_og_validate_paymen_f535678725(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.payment_confirmations; OLD og_compat.payment_confirmations;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='payment_confirmations';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  i og_compat.payment_intents; n NUMERIC;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.payment_confirmations,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.payment_confirmations,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT i FROM og_compat.payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF i.purpose='CHECKOUT_GROUP' AND EXISTS(SELECT 1 FROM og_compat.payment_confirmations
        WHERE intent_id=i.intent_id AND disposition='ALLOCATABLE') THEN
        SELECT COALESCE(sum(amount),0) INTO n FROM og_compat.payment_allocations WHERE intent_id=i.intent_id;
        IF n<>i.expected_amount OR EXISTS(SELECT 1 FROM og_compat.orders o WHERE o.group_id=i.group_id
            AND NOT EXISTS(SELECT 1 FROM og_compat.payment_allocations a WHERE a.order_id=o.order_id AND a.intent_id=i.intent_id)) THEN
            RAISE EXCEPTION 'Confirmed payment must allocate every order exactly' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_payment_intents_og_guard_payment_intent(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_payment_intents_og_guard_payment_intent(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.payment_intents; OLD og_compat.payment_intents;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='payment_intents';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.payment_intents,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.payment_intents,coalesce(p_old,'{}'::jsonb));
    IF NEW.purpose='CHECKOUT_GROUP' AND NOT EXISTS(
        SELECT 1 FROM og_compat.checkout_groups WHERE group_id=NEW.group_id AND expected_total=NEW.expected_amount
            AND payment_due_at=NEW.deadline AND payment_method=NEW.payment_method) THEN
        RAISE EXCEPTION 'Payment amount/deadline/method differs from checkout' USING ERRCODE='23514';
    END IF;
    IF NEW.purpose='LISTING_FEE' AND NOT EXISTS(
        SELECT 1 FROM og_compat.listing_fee_charges WHERE charge_id=NEW.listing_charge_id AND amount=NEW.expected_amount) THEN
        RAISE EXCEPTION 'Payment differs from listing fee charge' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND ROW(NEW.purpose,NEW.group_id,NEW.listing_charge_id,NEW.expected_amount,NEW.currency,
        NEW.payment_method,NEW.deadline,NEW.created_at,NEW.command_key)
        IS DISTINCT FROM ROW(OLD.purpose,OLD.group_id,OLD.listing_charge_id,OLD.expected_amount,OLD.currency,
        OLD.payment_method,OLD.deadline,OLD.created_at,OLD.command_key) THEN
        RAISE EXCEPTION 'Payment intent snapshot is immutable' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


