 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.payment_intents,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.payment_intents,coalesce(p_old,'{}'::jsonb));
    IF EXISTS(SELECT 1 FROM og_compat.payment_intents i WHERE i.intent_id=NEW.intent_id AND i.state='CONFIRMED'
        AND NOT EXISTS(SELECT 1 FROM og_compat.payment_confirmations c WHERE c.intent_id=i.intent_id AND disposition='ALLOCATABLE')) THEN
        RAISE EXCEPTION 'Confirmed intent needs verified confirmation' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_penalty_ledger_og_guard_penalty_entry(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_penalty_ledger_og_guard_penalty_entry(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.penalty_ledger; OLD og_compat.penalty_ledger;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='penalty_ledger';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  points BIGINT;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.penalty_ledger,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.penalty_ledger,coalesce(p_old,'{}'::jsonb));
    PERFORM 1 FROM og_compat.users WHERE user_id=NEW.user_id FOR UPDATE;
    SELECT COALESCE(sum(points_delta),0) INTO points FROM og_compat.penalty_ledger WHERE user_id=NEW.user_id;
    IF NOT og_has_role(NEW.decided_by,'KTV') OR points+NEW.points_delta<0
        OR (NEW.points_delta>0 AND NOT EXISTS(SELECT 1 FROM og_compat.reports
            WHERE report_id=NEW.report_id AND status='RESOLVED'))
        OR (NEW.adjustment_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.penalty_ledger
            WHERE entry_id=NEW.adjustment_of AND user_id=NEW.user_id)) THEN
        RAISE EXCEPTION 'Penalty requires confirmed KTV violation/correction' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


