--
-- Name: og70_row_pickup_attempts_og_guard_pickup_attempt(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_pickup_attempts_og_guard_pickup_attempt(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.pickup_attempts; OLD og_compat.pickup_attempts;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='pickup_attempts';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  s og_compat.shipments;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.pickup_attempts,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.pickup_attempts,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT s FROM og_compat.shipments WHERE shipment_id=NEW.shipment_id FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.leg<>'RETURN' OR NEW.attempted_at<s.initiated_at OR NEW.attempted_at>s.pickup_deadline
       OR NEW.attempt_no<>(SELECT count(*)+1 FROM og_compat.pickup_attempts WHERE shipment_id=s.shipment_id)
       OR (SELECT count(*) FROM og_compat.pickup_attempts WHERE shipment_id=s.shipment_id AND outcome='FAILED')>=3
       OR EXISTS(SELECT 1 FROM og_compat.pickup_attempts WHERE shipment_id=s.shipment_id AND outcome='PICKED_UP')
       OR NOT EXISTS(SELECT 1 FROM og_compat.shipment_events WHERE event_id=NEW.source_event_id AND shipment_id=s.shipment_id) THEN
        RAISE EXCEPTION 'Pickup deadline/count/source exceeded' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


