--
-- Name: og70_row_product_media_fn_enforce_product_media_limits(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_product_media_fn_enforce_product_media_limits(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.product_media; OLD og_compat.product_media;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='product_media';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  n INTEGER;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.product_media,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.product_media,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='UPDATE' AND NEW.product_id<>OLD.product_id THEN
        RAISE EXCEPTION 'Cannot move media between products' USING ERRCODE='23514';
    END IF;
    PERFORM 1 FROM og_compat.products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT count(*) INTO n FROM og_compat.product_media WHERE product_id=NEW.product_id
        AND media_type=NEW.media_type AND media_id IS DISTINCT FROM NEW.media_id;
    IF n >= (CASE NEW.media_type WHEN 'IMAGE' THEN 5 ELSE 2 END) THEN
        RAISE EXCEPTION 'Product media limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


