$$;


--
-- Name: og70_row_product_revisions_og_guard_product_revision(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_product_revisions_og_guard_product_revision(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.product_revisions; OLD og_compat.product_revisions;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='product_revisions';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.product_revisions,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.product_revisions,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='INSERT' THEN
        IF NEW.provenance='UC83' AND NEW.state<>'DRAFT' THEN
            RAISE EXCEPTION 'UC83 revision starts as draft' USING ERRCODE='23514';
        END IF;
        RETURN to_jsonb(NEW);
    END IF;
    IF TG_OP='DELETE' OR OLD.state<>'DRAFT' THEN
        RAISE EXCEPTION 'Product revision history is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state='SUBMITTED' AND (
        (SELECT count(*) FROM og_compat.revision_media WHERE revision_id=NEW.revision_id AND media_type='IMAGE') NOT BETWEEN 1 AND 5
        OR (SELECT count(*) FROM og_compat.revision_media WHERE revision_id=NEW.revision_id AND media_type='VIDEO') NOT BETWEEN 1 AND 2) THEN
        RAISE EXCEPTION 'Submission requires images and videos' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_products_fn_check_product_media_requirements(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_products_fn_check_product_media_requirements(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.products; OLD og_compat.products;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='products';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

    v_image_count INTEGER;
    v_video_count INTEGER;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.products,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.products,coalesce(p_old,'{}'::jsonb));
    IF NEW.status IN ('PENDING', 'ACTIVE') AND (OLD.status IS NULL OR OLD.status = 'DRAFT') THEN
        SELECT COUNT(*) FILTER (WHERE media_type = 'IMAGE'),
               COUNT(*) FILTER (WHERE media_type = 'VIDEO')
        INTO v_image_count, v_video_count
        FROM og_compat.product_media
        WHERE product_id = NEW.product_id;

        IF v_image_count < 1 THEN
            RAISE EXCEPTION 'Tin đăng phải có ít nhất 1 hình ảnh sản phẩm (media_type=IMAGE).';
        END IF;

        IF v_video_count < 1 THEN
            RAISE EXCEPTION 'Tin đăng đồ cũ phải có ít nhất 1 video quay cận cảnh sản phẩm (media_type=VIDEO).';
        END IF;
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_products_og_guard_listing_activation(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_products_og_guard_listing_activation(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.products; OLD og_compat.products;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='products';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.products,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.products,coalesce(p_old,'{}'::jsonb));
    IF NEW.workflow_model='UC83' AND NEW.status='ACTIVE' THEN
        IF NEW.current_revision_id IS DISTINCT FROM NEW.public_revision_id OR NOT EXISTS (
            SELECT 1 FROM og_compat.product_revisions r JOIN og_compat.listing_fee_assessments a USING(revision_id)
            WHERE r.revision_id=NEW.public_revision_id AND r.product_id=NEW.product_id AND r.provenance='UC83'
              AND r.listed_unit_price=NEW.listed_price AND r.quantity=NEW.quantity_total
              AND r.return_allowed IS NOT DISTINCT FROM NEW.return_allowed
              AND r.delivery_options=NEW.delivery_options
              AND (a.amount_due=0 OR EXISTS(SELECT 1 FROM og_compat.listing_fee_receipts receipt
                  JOIN og_compat.listing_fee_charges c USING(charge_id) WHERE c.assessment_id=a.assessment_id))
        ) OR NOT EXISTS(SELECT 1 FROM og_compat.seller_profiles s JOIN og_compat.seller_profile_decisions d USING(seller_profile_id)
            WHERE s.user_id=NEW.seller_id AND s.state='APPROVED' AND d.revision_no=s.revision_no
              AND d.outcome='APPROVED') OR NOT og_has_role(NEW.seller_id,'SELLER') THEN
            RAISE EXCEPTION 'ACTIVE requires current KTV approval, confirmed listing fee and seller approval'
                USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_quick_auth_attempts_og_guard_quick_auth_attempt(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_quick_auth_attempts_og_guard_quick_auth_attempt(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.quick_auth_attempts; OLD og_compat.quick_auth_attempts;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='quick_auth_attempts';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  s og_compat.quick_auth_sessions;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.quick_auth_attempts,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.quick_auth_attempts,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT s FROM og_compat.quick_auth_sessions WHERE session_id=NEW.session_id FOR UPDATE;
    NEW.attempted_at:=clock_timestamp();
    IF s.expires_at<=NEW.attempted_at OR s.nonmatch_count>=15 OR EXISTS(SELECT 1 FROM og_compat.quick_auth_attempts
        WHERE session_id=s.session_id AND result='MATCH') OR NOT EXISTS(
        SELECT 1 FROM og_compat.ekyc_profiles p JOIN og_compat.ekyc_decisions d USING(profile_id)
        JOIN og_compat.ekyc_private_assets a ON a.profile_id=p.profile_id WHERE p.profile_id=s.profile_id
          AND p.state='VERIFIED' AND d.outcome='VERIFIED' AND p.reference_expires_at>NEW.attempted_at
          AND a.asset_id=s.reference_asset_id AND a.asset_type='REFERENCE' AND a.deleted_at IS NULL
          AND a.expires_at>NEW.attempted_at
          AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles pending WHERE pending.user_id=s.user_id
              AND pending.state IN ('DRAFT','IN_PROGRESS','PENDING'))) THEN
        RAISE EXCEPTION 'Quick authentication unavailable/exhausted' USING ERRCODE='23514';
    END IF;
    IF s.last_nonmatch_at IS NOT NULL AND NEW.attempted_at<s.last_nonmatch_at+INTERVAL '3 seconds' THEN
        RAISE EXCEPTION 'Quick authentication cooldown' USING ERRCODE='23514';
    END IF;
    IF NEW.result='NON_MATCH' THEN UPDATE og_compat.quick_auth_sessions SET nonmatch_count=nonmatch_count+1,
        last_nonmatch_at=NEW.attempted_at WHERE session_id=s.session_id; END IF;
    RETURN to_jsonb(NEW);
END;
$$;


