BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.quick_auth_results,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.quick_auth_results,coalesce(p_old,'{}'::jsonb));
