-- Name: og70_row_reward_accounts_og_guard_reward_account(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_reward_accounts_og_guard_reward_account(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.reward_accounts; OLD og_compat.reward_accounts;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='reward_accounts';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.reward_accounts,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.reward_accounts,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='DELETE' OR (TG_OP='INSERT' AND (NEW.balance<>0 OR NEW.version<>0))
        OR (TG_OP='UPDATE' AND (NEW.user_id<>OLD.user_id OR p_depth<2)) THEN
        RAISE EXCEPTION 'Reward balance only changes through ledger' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_reward_ledger_og_apply_reward_entry(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_reward_ledger_og_apply_reward_entry(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.reward_ledger; OLD og_compat.reward_ledger;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='reward_ledger';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  b BIGINT;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.reward_ledger,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.reward_ledger,coalesce(p_old,'{}'::jsonb));
    SELECT balance INTO STRICT b FROM og_compat.reward_accounts WHERE user_id=NEW.user_id FOR UPDATE;
    IF b+NEW.points_delta<0 OR (NEW.entry_type='CREDIT_COMPLETION' AND NOT EXISTS(
        SELECT 1 FROM og_compat.orders WHERE order_id=NEW.order_id AND status='COMPLETED'
            AND NEW.user_id IN (buyer_id,seller_id)))
        OR (NEW.entry_type='CORRECTION' AND NOT og_has_role(NEW.actor_id,'ADMIN')) THEN
        RAISE EXCEPTION 'Reward source/balance not eligible' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.reward_accounts SET balance=balance+NEW.points_delta,version=version+1 WHERE user_id=NEW.user_id;
    RETURN to_jsonb(NEW);
END;
$$;


