--
-- Name: og70_row_shipments_og_guard_return_shipment(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_shipments_og_guard_return_shipment(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.shipments; OLD og_compat.shipments;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='shipments';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  c og_compat.cases;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.shipments,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.shipments,coalesce(p_old,'{}'::jsonb));
    IF NEW.workflow_model='UC83' AND NEW.leg='RETURN' THEN
        SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.return_case_id FOR UPDATE;
        IF c.order_id<>NEW.order_id OR c.case_type<>'RETURN' OR c.approved_at IS NULL THEN
            RAISE EXCEPTION 'Return shipment requires approval for the same order' USING ERRCODE='23514';
        END IF;
        NEW.pickup_expected_at:=c.approved_at+INTERVAL '24 hours';
        NEW.pickup_deadline:=c.approved_at+INTERVAL '3 days';
    END IF;
    IF TG_OP='UPDATE' AND NEW.workflow_model='UC83' AND
        ROW(NEW.order_id,NEW.leg,NEW.return_case_id,NEW.delivery_method,NEW.initiated_at)
        IS DISTINCT FROM ROW(OLD.order_id,OLD.leg,OLD.return_case_id,OLD.delivery_method,OLD.initiated_at) THEN
        RAISE EXCEPTION 'Shipment identity/method snapshot cannot silently change' USING ERRCODE='23514';
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


--
-- Name: og70_row_user_roles_og_validate_canonical_role(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_user_roles_og_validate_canonical_role(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.user_roles; OLD og_compat.user_roles;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='user_roles';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  role_code TEXT;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.user_roles,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.user_roles,coalesce(p_old,'{}'::jsonb));
    IF NOT EXISTS(SELECT 1 FROM og_compat.users WHERE user_id=NEW.user_id AND identity_workflow='UC83') THEN RETURN NULL; END IF;
    SELECT role_name INTO role_code FROM og_compat.roles WHERE role_id=NEW.role_id;
    IF (role_code='SELLER' AND NOT EXISTS(SELECT 1 FROM og_compat.seller_profiles p JOIN og_compat.seller_profile_decisions d USING(seller_profile_id)
        WHERE p.user_id=NEW.user_id AND p.state='APPROVED' AND p.revision_no=d.revision_no AND d.outcome='APPROVED'))
        OR (role_code IN ('KTV','ADMIN') AND NOT og_has_role(NEW.granted_by,'ADMIN')) THEN
        RAISE EXCEPTION 'Canonical role grant requires approval authority' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og70_row_users_og_record_account_status(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_users_og_record_account_status(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.users; OLD og_compat.users;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='users';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.users,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.users,coalesce(p_old,'{}'::jsonb));
    IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO og_compat.account_status_events(user_id,old_status,new_status)
            VALUES(NEW.user_id,CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END,NEW.status);
    END IF;
    RETURN to_jsonb(NEW);
END;
$$;


