--
-- Name: og70_row_voucher_revisions_og_guard_voucher_policy(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_voucher_revisions_og_guard_voucher_policy(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.voucher_revisions; OLD og_compat.voucher_revisions;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='voucher_revisions';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  v og_compat.vouchers;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.voucher_revisions,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.voucher_revisions,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT v FROM og_compat.vouchers WHERE voucher_id=NEW.voucher_id;
    IF NOT og_has_role(NEW.created_by,'ADMIN') OR v.voucher_type='BUYER_FEE_DISCOUNT' THEN
        RAISE EXCEPTION 'Admin authors canonical goods/shipping policies' USING ERRCODE='23514'; END IF;
    NEW.benefit_component:=COALESCE(NEW.benefit_component,CASE v.voucher_type WHEN 'SHIPPING_DISCOUNT' THEN 'SHIPPING' ELSE 'GOODS' END);
    NEW.discount_type:=COALESCE(NEW.discount_type,v.discount_type);
    NEW.discount_value:=COALESCE(NEW.discount_value,v.discount_value);
    NEW.max_discount_amount:=COALESCE(NEW.max_discount_amount,v.max_discount_amount);
    NEW.min_eligible_amount:=COALESCE(NEW.min_eligible_amount,v.min_order_amount);
    RETURN to_jsonb(NEW);
END;
$$;


