--
-- Name: og70_row_zero_checkout_confirmations_og_confirm_z_68e9aac39d(jsonb, jsonb, text, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_row_zero_checkout_confirmations_og_confirm_z_68e9aac39d(p_new jsonb, p_old jsonb, p_op text, p_phase text, p_depth integer, p_args text[]) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE
 NEW og_compat.zero_checkout_confirmations; OLD og_compat.zero_checkout_confirmations;
 TG_OP text:=p_op; TG_WHEN text:=p_phase; TG_TABLE_NAME text:='zero_checkout_confirmations';
 TG_TABLE_SCHEMA text:='og_compat'; TG_ARGV text[]:=p_args; TG_NARGS integer:=cardinality(p_args);
  g og_compat.checkout_groups;

BEGIN
 NEW:=jsonb_populate_record(NULL::og_compat.zero_checkout_confirmations,coalesce(p_new,'{}'::jsonb));
 OLD:=jsonb_populate_record(NULL::og_compat.zero_checkout_confirmations,coalesce(p_old,'{}'::jsonb));
    SELECT * INTO STRICT g FROM og_compat.checkout_groups WHERE group_id=NEW.group_id FOR UPDATE;
    NEW.confirmed_at:=clock_timestamp();
    IF g.expected_total<>0 OR g.state<>'READY' OR NEW.confirmed_at>=g.payment_due_at
        OR NOT EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=g.group_id)
        OR EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=g.group_id AND (total_amount<>0 OR status<>'PAYMENT_PENDING'))
        OR EXISTS(SELECT 1 FROM og_compat.payment_intents WHERE group_id=g.group_id) THEN
        RAISE EXCEPTION 'Zero checkout needs an in-time, unpaid, fully subsidized group' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.orders SET status='PAID_HELD',paid_confirmed_at=NEW.confirmed_at,
        seller_accept_due_at=NEW.confirmed_at+INTERVAL '2 days' WHERE group_id=g.group_id;
    UPDATE og_compat.inventory_reservations r SET state='FUNDED' FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id)
        WHERE r.order_item_id=i.order_item_id AND o.group_id=g.group_id AND r.state='HELD';
    UPDATE og_compat.checkout_groups SET state='PAID' WHERE group_id=g.group_id;
    RETURN to_jsonb(NEW);
END;
$$;


