--
-- Name: og70_validate_graph(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_validate_graph(force_all boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'og_compat'
    AS $$
DECLARE dirty jsonb:=coalesce(nullif(current_setting('og70.dirty',true),''),'{}')::jsonb; row record;
BEGIN
 IF force_all THEN dirty:='{"carts":true,"cases":true,"roles":true,"users":true,"offers":true,"orders":true,"reports":true,"reviews":true,"messages":true,"payments":true,"products":true,"vouchers":true,"addresses":true,"shipments":true,"audit_logs":true,"cart_items":true,"categories":true,"complaints":true,"user_roles":true,"case_events":true,"case_rounds":true,"money_holds":true,"order_items":true,"order_events":true,"case_evidence":true,"conversations":true,"ekyc_profiles":true,"notifications":true,"outbox_events":true,"product_media":true,"reward_ledger":true,"case_decisions":true,"ekyc_decisions":true,"order_vouchers":true,"penalty_ledger":true,"revision_media":true,"voucher_grants":true,"auth_challenges":true,"checkout_groups":true,"payment_intents":true,"pickup_attempts":true,"reward_accounts":true,"reward_policies":true,"seller_profiles":true,"shipment_events":true,"payment_attempts":true,"penalty_policies":true,"review_revisions":true,"product_revisions":true,"voucher_revisions":true,"checklist_policies":true,"interaction_events":true,"payment_ipn_events":true,"product_categories":true,"quick_auth_results":true,"report_export_runs":true,"ekyc_private_assets":true,"external_identities":true,"listing_fee_charges":true,"media_analysis_runs":true,"payment_allocations":true,"quick_auth_attempts":true,"quick_auth_sessions":true,"seller_buyer_blocks":true,"system_fee_policies":true,"account_restrictions":true,"checkout_redemptions":true,"discount_allocations":true,"listing_fee_policies":true,"listing_fee_receipts":true,"seller_verifications":true,"voucher_grant_events":true,"account_status_events":true,"order_fund_components":true,"payment_confirmations":true,"payment_review_audits":true,"settlement_operations":true,"handover_confirmations":true,"inventory_reservations":true,"notification_reminders":true,"payment_alert_requests":true,"user_security_settings":true,"vnpay_payment_attempts":true,"chat_media_daily_quotas":true,"conversation_user_state":true,"listing_fee_assessments":true,"notification_deliveries":true,"notification_dispatches":true,"conversation_order_links":true,"order_unboxing_evidences":true,"payment_ipn_raw_receipts":true,"seller_profile_decisions":true,"password_reset_challenges":true,"voucher_revision_products":true,"ekyc_verification_attempts":true,"identity_document_registry":true,"outbox_consumer_checkpoints":true,"seller_verification_metrics":true,"zero_checkout_confirmations":true,"payment_reconciliation_cases":true,"product_moderation_decisions":true,"voucher_revision_revocations":true,"product_moderation_legacy_history":true}'::jsonb; END IF;
IF dirty ? 'carts' THEN
 FOR row IN SELECT to_jsonb(r) AS j FROM og_compat.carts r LOOP PERFORM og70_validate_row('carts',row.j,true); END LOOP;
IF EXISTS(SELECT 1 FROM og_compat.carts r WHERE r.user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.users p WHERE p.user_id=r.user_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint fk_carts_user' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.carts WHERE (cart_id) IS NOT NULL GROUP BY cart_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint carts_pkey' USING ERRCODE='23505'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.carts WHERE (user_id) IS NOT NULL GROUP BY user_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint carts_user_id_key' USING ERRCODE='23505'; END IF;
END IF;
IF dirty ? 'cases' THEN
 FOR row IN SELECT to_jsonb(r) AS j FROM og_compat.cases r LOOP PERFORM og70_validate_row('cases',row.j,true); END LOOP;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.assigned_to IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.users p WHERE p.user_id=r.assigned_to) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_assigned_to_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.created_by IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.users p WHERE p.user_id=r.created_by) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_created_by_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.listing_charge_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.listing_fee_charges p WHERE p.charge_id=r.listing_charge_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_listing_charge_id_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.orders p WHERE p.order_id=r.order_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_order_id_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.payment_intent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.payment_intents p WHERE p.intent_id=r.payment_intent_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_payment_intent_id_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.products p WHERE p.product_id=r.product_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_product_id_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases r WHERE r.target_user_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.users p WHERE p.user_id=r.target_user_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_target_user_id_fkey' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases WHERE (command_key) IS NOT NULL GROUP BY command_key HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_command_key_key' USING ERRCODE='23505'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases WHERE (case_id) IS NOT NULL GROUP BY case_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint cases_pkey' USING ERRCODE='23505'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.cases WHERE (order_id) IS NOT NULL AND ((((case_type)::text = 'RETURN'::text) AND ((state)::text <> ALL (ARRAY[('CLOSED'::character varying)::text, ('REJECTED'::character varying)::text])))) GROUP BY order_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint uq_return_case_active' USING ERRCODE='23505'; END IF;
END IF;
IF dirty ? 'roles' THEN
 FOR row IN SELECT to_jsonb(r) AS j FROM og_compat.roles r LOOP PERFORM og70_validate_row('roles',row.j,true); END LOOP;
IF EXISTS(SELECT 1 FROM og_compat.roles WHERE (role_id) IS NOT NULL GROUP BY role_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint roles_pkey' USING ERRCODE='23505'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.roles WHERE (role_name) IS NOT NULL GROUP BY role_name HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint roles_role_name_key' USING ERRCODE='23505'; END IF;
END IF;
IF dirty ? 'users' THEN
 FOR row IN SELECT to_jsonb(r) AS j FROM og_compat.users r LOOP PERFORM og70_validate_row('users',row.j,true); END LOOP;
IF EXISTS(SELECT 1 FROM og_compat.users WHERE (user_id) IS NOT NULL GROUP BY user_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint users_pkey' USING ERRCODE='23505'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.users WHERE (email) IS NOT NULL GROUP BY email HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint uq_users_email' USING ERRCODE='23505'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.users WHERE (phone_number) IS NOT NULL AND ((phone_number IS NOT NULL)) GROUP BY phone_number HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint uq_users_phone_number' USING ERRCODE='23505'; END IF;
END IF;
IF dirty ? 'offers' THEN
 FOR row IN SELECT to_jsonb(r) AS j FROM og_compat.offers r LOOP PERFORM og70_validate_row('offers',row.j,true); END LOOP;
IF EXISTS(SELECT 1 FROM og_compat.offers r WHERE r.conversation_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.conversations p WHERE p.conversation_id=r.conversation_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint fk_offers_conversation' USING ERRCODE='23503'; END IF;
IF EXISTS(SELECT 1 FROM og_compat.offers r WHERE r.fee_policy_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.system_fee_policies p WHERE p.fee_policy_id=r.fee_policy_id) LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint fk_offers_fee_policy' USING ERRCODE='23503'; END IF;
