IF EXISTS(SELECT 1 FROM og_compat.product_moderation_legacy_history WHERE (decision_id) IS NOT NULL GROUP BY decision_id HAVING count(*)>1 LIMIT 1) THEN RAISE EXCEPTION 'Relational constraint product_moderation_legacy_history_pkey' USING ERRCODE='23505'; END IF;
END IF;
 PERFORM set_config('og70.dirty','{}',true);
END $$;


--
-- Name: og70_validate_row(text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og70_validate_row(s text, j jsonb, skip_not_valid boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE bad boolean;
BEGIN
 IF j IS NULL THEN RETURN; END IF;
 CASE s
WHEN 'carts' THEN
IF j->'cart_id' IS NULL OR j->'cart_id'='null'::jsonb OR j->'user_id' IS NULL OR j->'user_id'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb THEN RAISE EXCEPTION 'Required field in carts' USING ERRCODE='23502'; END IF;
NULL;
WHEN 'cases' THEN
IF j->'case_id' IS NULL OR j->'case_id'='null'::jsonb OR j->'case_type' IS NULL OR j->'case_type'='null'::jsonb OR j->'created_by' IS NULL OR j->'created_by'='null'::jsonb OR j->'description' IS NULL OR j->'description'='null'::jsonb OR j->'state' IS NULL OR j->'state'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb OR j->'command_key' IS NULL OR j->'command_key'='null'::jsonb THEN RAISE EXCEPTION 'Required field in cases' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT (((case_type)::text = ANY (ARRAY[(''RETURN''::character varying)::text, (''SYSTEM_ISSUE''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_case_type_check' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((((((((order_id IS NOT NULL))::integer + ((product_id IS NOT NULL))::integer) + ((listing_charge_id IS NOT NULL))::integer) + ((payment_intent_id IS NOT NULL))::integer) + ((target_user_id IS NOT NULL))::integer) = 1)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_check' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((((case_type)::text <> ''RETURN''::text) OR (order_id IS NOT NULL))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_check1' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((valid_returned_at IS NULL) OR ((approved_at IS NOT NULL) AND (valid_returned_at >= approved_at) AND (seller_response_due_at = (valid_returned_at + ''2 days''::interval))))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_check2' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((((state)::text <> ALL (ARRAY[(''CLOSED''::character varying)::text, (''REJECTED''::character varying)::text])) OR (closed_at IS NOT NULL))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_check3' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((btrim(description) <> ''''::text)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_description_check' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((state)::text = ANY (ARRAY[(''OPEN''::character varying)::text, (''REVIEWING''::character varying)::text, (''RETURN_APPROVED''::character varying)::text, (''RETURNING''::character varying)::text, (''POST_RETURN''::character varying)::text, (''CLOSED''::character varying)::text, (''REJECTED''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.cases,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint cases_state_check' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'roles' THEN
IF j->'role_id' IS NULL OR j->'role_id'='null'::jsonb OR j->'role_name' IS NULL OR j->'role_name'='null'::jsonb THEN RAISE EXCEPTION 'Required field in roles' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT (((role_name)::text = ANY (ARRAY[(''BUYER''::character varying)::text, (''SELLER''::character varying)::text, (''ADMIN''::character varying)::text, (''KTV''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.roles,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_roles_name' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'users' THEN
IF j->'user_id' IS NULL OR j->'user_id'='null'::jsonb OR j->'email' IS NULL OR j->'email'='null'::jsonb OR j->'password_hash' IS NULL OR j->'password_hash'='null'::jsonb OR j->'full_name' IS NULL OR j->'full_name'='null'::jsonb OR j->'status' IS NULL OR j->'status'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb OR j->'identity_workflow' IS NULL OR j->'identity_workflow'='null'::jsonb THEN RAISE EXCEPTION 'Required field in users' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT (((deleted_at IS NULL) OR ((status)::text = ''DEACTIVATED''::text))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.users,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_users_deleted_state' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((email)::text = lower(btrim((email)::text)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.users,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_users_email_normalized' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((identity_workflow)::text = ANY (ARRAY[(''LEGACY_V14''::character varying)::text, (''UC83''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.users,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_users_identity_workflow' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((status)::text = ANY (ARRAY[(''ACTIVE''::character varying)::text, (''SUSPENDED''::character varying)::text, (''LOCKED''::character varying)::text, (''DEACTIVATED''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.users,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_users_status' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'offers' THEN
IF j->'offer_id' IS NULL OR j->'offer_id'='null'::jsonb OR j->'offered_item_price' IS NULL OR j->'offered_item_price'='null'::jsonb OR j->'status' IS NULL OR j->'status'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb OR j->'conversation_id' IS NULL OR j->'conversation_id'='null'::jsonb OR j->'proposer_id' IS NULL OR j->'proposer_id'='null'::jsonb OR j->'fee_policy_id' IS NULL OR j->'fee_policy_id'='null'::jsonb OR j->'buyer_system_fee' IS NULL OR j->'buyer_system_fee'='null'::jsonb OR j->'seller_system_fee' IS NULL OR j->'seller_system_fee'='null'::jsonb OR j->'buyer_subtotal' IS NULL OR j->'buyer_subtotal'='null'::jsonb OR j->'seller_proceeds' IS NULL OR j->'seller_proceeds'='null'::jsonb OR j->'currency' IS NULL OR j->'currency'='null'::jsonb OR j->'version' IS NULL OR j->'version'='null'::jsonb THEN RAISE EXCEPTION 'Required field in offers' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT ((currency = ''VND''::bpchar)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_currency' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((expires_at IS NULL) OR (expires_at > created_at))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_expiry' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((buyer_system_fee >= (0)::numeric) AND (seller_system_fee >= (0)::numeric) AND (seller_system_fee <= offered_item_price) AND (buyer_subtotal = (offered_item_price + buyer_system_fee)) AND (seller_proceeds = (offered_item_price - seller_system_fee)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_fees' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((offered_item_price > (0)::numeric)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_item_price' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((parent_offer_id IS NULL) OR (parent_offer_id <> offer_id))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_not_self_parent' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((((status)::text = ''PENDING''::text) AND (responded_at IS NULL) AND (responded_by IS NULL)) OR (((status)::text = ''EXPIRED''::text) AND (responded_at IS NOT NULL) AND (responded_by IS NULL)) OR (((status)::text = ''WITHDRAWN''::text) AND (responded_at IS NOT NULL) AND (responded_by = proposer_id)) OR (((status)::text = ANY (ARRAY[(''ACCEPTED''::character varying)::text, (''REJECTED''::character varying)::text, (''COUNTERED''::character varying)::text])) AND (responded_at IS NOT NULL) AND (responded_by IS NOT NULL) AND (responded_by <> proposer_id)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_response' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((status)::text = ANY (ARRAY[(''PENDING''::character varying)::text, (''ACCEPTED''::character varying)::text, (''REJECTED''::character varying)::text, (''COUNTERED''::character varying)::text, (''WITHDRAWN''::character varying)::text, (''EXPIRED''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.offers,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_offers_status' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'orders' THEN
IF j->'order_id' IS NULL OR j->'order_id'='null'::jsonb OR j->'checkout_group_id' IS NULL OR j->'checkout_group_id'='null'::jsonb OR j->'buyer_id' IS NULL OR j->'buyer_id'='null'::jsonb OR j->'seller_id' IS NULL OR j->'seller_id'='null'::jsonb OR j->'shipping_recipient_name' IS NULL OR j->'shipping_recipient_name'='null'::jsonb OR j->'shipping_phone_number' IS NULL OR j->'shipping_phone_number'='null'::jsonb OR j->'shipping_province' IS NULL OR j->'shipping_province'='null'::jsonb OR j->'shipping_district' IS NULL OR j->'shipping_district'='null'::jsonb OR j->'shipping_ward' IS NULL OR j->'shipping_ward'='null'::jsonb OR j->'shipping_detail_address' IS NULL OR j->'shipping_detail_address'='null'::jsonb OR j->'subtotal' IS NULL OR j->'subtotal'='null'::jsonb OR j->'shipping_fee' IS NULL OR j->'shipping_fee'='null'::jsonb OR j->'total_amount' IS NULL OR j->'total_amount'='null'::jsonb OR j->'currency' IS NULL OR j->'currency'='null'::jsonb OR j->'status' IS NULL OR j->'status'='null'::jsonb OR j->'payment_due_at' IS NULL OR j->'payment_due_at'='null'::jsonb OR j->'version' IS NULL OR j->'version'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb OR j->'buyer_system_fee' IS NULL OR j->'buyer_system_fee'='null'::jsonb OR j->'seller_system_fee' IS NULL OR j->'seller_system_fee'='null'::jsonb OR j->'seller_proceeds' IS NULL OR j->'seller_proceeds'='null'::jsonb OR j->'voucher_discount_amount' IS NULL OR j->'voucher_discount_amount'='null'::jsonb OR j->'shipping_discount_amount' IS NULL OR j->'shipping_discount_amount'='null'::jsonb OR j->'sponsor_type' IS NULL OR j->'sponsor_type'='null'::jsonb OR j->'workflow_model' IS NULL OR j->'workflow_model'='null'::jsonb OR j->'points_discount_amount' IS NULL OR j->'points_discount_amount'='null'::jsonb THEN RAISE EXCEPTION 'Required field in orders' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT ((points_discount_amount >= (0)::numeric)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint orders_points_discount_amount_check' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((((status)::text = ''COMPLETED''::text) AND (completed_at IS NOT NULL) AND (cancelled_at IS NULL) AND (cancellation_reason IS NULL)) OR (((status)::text = ''CANCELLED''::text) AND (cancelled_at IS NOT NULL) AND (completed_at IS NULL) AND (cancellation_reason IS NOT NULL)) OR (((status)::text <> ALL (ARRAY[(''COMPLETED''::character varying)::text, (''CANCELLED''::character varying)::text])) AND (completed_at IS NULL) AND (cancelled_at IS NULL) AND (cancellation_reason IS NULL)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_orders_terminal_time' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((early_completed_at IS NULL) OR ((valid_delivered_at IS NOT NULL) AND (early_completed_at >= valid_delivered_at) AND (early_completion_warning_version IS NOT NULL)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_order_early_completion' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((return_due_at IS NULL) OR (return_allowed AND (valid_delivered_at IS NOT NULL) AND (return_due_at = (valid_delivered_at + ''3 days''::interval))))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_order_return_window' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((((workflow_model)::text = ''LEGACY_V14''::text) OR ((group_id IS NOT NULL) AND (group_id = checkout_group_id) AND (return_allowed IS NOT NULL) AND ((delivery_method)::text = ANY (ARRAY[(''CARRIER''::character varying)::text, (''SELF_PICKUP''::character varying)::text, (''SELF_DELIVERY''::character varying)::text])) AND (handover_day IS NOT NULL)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_order_uc83_snapshot' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((subtotal > (0)::numeric) AND (shipping_fee >= (0)::numeric) AND (voucher_discount_amount >= (0)::numeric) AND ((shipping_discount_amount >= (0)::numeric) AND (shipping_discount_amount <= shipping_fee)) AND (buyer_system_fee >= (0)::numeric) AND ((seller_system_fee >= (0)::numeric) AND (seller_system_fee <= subtotal)) AND ((((workflow_model)::text = ''LEGACY_V14''::text) AND (points_discount_amount = (0)::numeric) AND ((voucher_discount_amount + shipping_discount_amount) < ((subtotal + buyer_system_fee) + shipping_fee)) AND (seller_proceeds = ((subtotal -
CASE
    WHEN ((sponsor_type)::text = ''SELLER''::text) THEN voucher_discount_amount
    ELSE (0)::numeric
END) - seller_system_fee)) AND (total_amount = ((((subtotal + buyer_system_fee) + shipping_fee) - voucher_discount_amount) - shipping_discount_amount))) OR (((workflow_model)::text = ''UC83''::text) AND (buyer_system_fee = (0)::numeric) AND (seller_system_fee = (0)::numeric) AND ((sponsor_type)::text = ''PLATFORM''::text) AND ((voucher_discount_amount + points_discount_amount) <= subtotal) AND (seller_proceeds = subtotal) AND (total_amount = ((((subtotal + shipping_fee) - voucher_discount_amount) - shipping_discount_amount) - points_discount_amount)) AND (total_amount >= (0)::numeric) AND (((delivery_method)::text = ''CARRIER''::text) OR (shipping_fee = (0)::numeric)))))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_orders_amounts' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((currency = ''VND''::bpchar)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_orders_currency' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((buyer_id <> seller_id)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_orders_distinct_users' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((payment_due_at > created_at)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_orders_payment_due' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((status)::text = ANY (ARRAY[(''PAYMENT_PENDING''::character varying)::text, (''PAID_HELD''::character varying)::text, (''SELLER_CONFIRMED''::character varying)::text, (''SHIPPED''::character varying)::text, (''DELIVERED''::character varying)::text, (''COMPLETED''::character varying)::text, (''CANCELLED''::character varying)::text, (''DISPUTED''::character varying)::text, (''REFUNDED''::character varying)::text, (''UNDER_REVIEW''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_orders_status' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((workflow_model)::text = ANY (ARRAY[(''LEGACY_V14''::character varying)::text, (''UC83''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.orders,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint orders_workflow_model_check' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'reports' THEN
IF j->'report_id' IS NULL OR j->'report_id'='null'::jsonb OR j->'reporter_id' IS NULL OR j->'reporter_id'='null'::jsonb OR j->'reason' IS NULL OR j->'reason'='null'::jsonb OR j->'status' IS NULL OR j->'status'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb THEN RAISE EXCEPTION 'Required field in reports' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT (((reported_user_id IS NULL) OR (reporter_id <> reported_user_id))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reports,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reports_not_self' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((reason)::text = ANY (ARRAY[(''FAKE_LISTING''::character varying)::text, (''SPAM''::character varying)::text, (''HARASSMENT''::character varying)::text, (''SUSPICIOUS_ACCOUNT''::character varying)::text, (''PROHIBITED_CONTENT''::character varying)::text, (''OTHER''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reports,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reports_reason' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((((status)::text = ANY (ARRAY[(''OPEN''::character varying)::text, (''REVIEWING''::character varying)::text])) AND (resolved_by IS NULL) AND (resolved_at IS NULL)) OR (((status)::text = ANY (ARRAY[(''RESOLVED''::character varying)::text, (''REJECTED''::character varying)::text])) AND (resolved_by IS NOT NULL) AND (resolved_at IS NOT NULL)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reports,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reports_resolution_fields' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((status)::text = ANY (ARRAY[(''OPEN''::character varying)::text, (''REVIEWING''::character varying)::text, (''RESOLVED''::character varying)::text, (''REJECTED''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reports,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reports_status' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((reported_user_id IS NOT NULL) OR (product_id IS NOT NULL))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reports,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reports_target' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'reviews' THEN
IF j->'review_id' IS NULL OR j->'review_id'='null'::jsonb OR j->'order_id' IS NULL OR j->'order_id'='null'::jsonb OR j->'reviewer_id' IS NULL OR j->'reviewer_id'='null'::jsonb OR j->'reviewee_id' IS NULL OR j->'reviewee_id'='null'::jsonb OR j->'rating' IS NULL OR j->'rating'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb THEN RAISE EXCEPTION 'Required field in reviews' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT ((reviewer_id <> reviewee_id)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reviews,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reviews_distinct_users' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((rating >= 1) AND (rating <= 5))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.reviews,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_reviews_rating' USING ERRCODE='23514'; END IF;
NULL;
WHEN 'messages' THEN
IF j->'message_id' IS NULL OR j->'message_id'='null'::jsonb OR j->'conversation_id' IS NULL OR j->'conversation_id'='null'::jsonb OR j->'sender_id' IS NULL OR j->'sender_id'='null'::jsonb OR j->'content' IS NULL OR j->'content'='null'::jsonb OR j->'message_type' IS NULL OR j->'message_type'='null'::jsonb OR j->'created_at' IS NULL OR j->'created_at'='null'::jsonb OR j->'client_message_id' IS NULL OR j->'client_message_id'='null'::jsonb OR j->'media_status' IS NULL OR j->'media_status'='null'::jsonb THEN RAISE EXCEPTION 'Required field in messages' USING ERRCODE='23502'; END IF;
EXECUTE 'SELECT (((edited_at IS NULL) OR (edited_at >= created_at))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.messages,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_messages_edit_time' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT ((length(btrim(content)) > 0)) IS FALSE FROM jsonb_populate_record(NULL::og_compat.messages,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_messages_content_not_blank' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((deleted_at IS NULL) OR (deleted_at >= created_at))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.messages,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_messages_delete_time' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((media_status)::text = ANY (ARRAY[(''ACTIVE''::character varying)::text, (''EXPIRED''::character varying)::text, (''HOLD_FOR_DISPUTE''::character varying)::text]))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.messages,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_messages_media_status' USING ERRCODE='23514'; END IF;
EXECUTE 'SELECT (((reply_to_message_id IS NULL) OR (reply_to_message_id <> message_id))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.messages,$1) r' INTO bad USING j;
IF bad THEN RAISE EXCEPTION 'Constraint ck_messages_not_self_reply' USING ERRCODE='23514'; END IF;
