EXECUTE 'SELECT (((((source_type)::text = ''IPN_EVENT''::text) AND (event_id IS NOT NULL) AND (review_audit_id IS NULL)) OR (((source_type)::text = ''REVIEW_DECISION''::text) AND (review_audit_id IS NOT NULL) AND (event_id IS NULL)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.payment_reconciliation_cases,$1) r' INTO bad USING j;
