EXECUTE 'SELECT (((((decision)::text = ''REJECTED''::text) AND (reason IS NOT NULL) AND (length(TRIM(BOTH FROM reason)) > 0)) OR (((decision)::text = ''APPROVED''::text) AND (reason IS NULL)))) IS FALSE FROM jsonb_populate_record(NULL::og_compat.product_moderation_decisions,$1) r' INTO bad USING j;
