SELECT x.j INTO result FROM jsonb_array_elements(stored) x(j) WHERE og70_key('outbox_consumer_checkpoints',x.j)=og70_key('outbox_consumer_checkpoints',writer.j);
RETURN jsonb_populate_record(NEW,result);
WHEN 'interaction_events' THEN
IF TG_OP='INSERT' THEN EXECUTE 'INSERT INTO public.interaction_events (event_id,user_id,guest_session_digest,event_type,product_id,query_text,occurred_at,source_key,record_type) SELECT r.event_id,r.user_id,r.guest_session_digest,r.event_type,r.product_id,r.query_text,r.occurred_at,r.source_key,''interaction_events'' FROM jsonb_populate_record(NULL::og_compat.interaction_events,$1) r RETURNING to_jsonb(interaction_events)' INTO stored USING j;
ELSIF TG_OP='UPDATE' THEN EXECUTE 'UPDATE public.interaction_events t SET event_id=r.event_id,user_id=r.user_id,guest_session_digest=r.guest_session_digest,event_type=r.event_type,product_id=r.product_id,query_text=r.query_text,occurred_at=r.occurred_at,source_key=r.source_key FROM jsonb_populate_record(NULL::og_compat.interaction_events,$1) r,jsonb_populate_record(NULL::og_compat.interaction_events,$2) old_r WHERE t.event_id=old_r.event_id AND t.record_type=''interaction_events'' AND jsonb_build_object(''event_id'',to_jsonb(t)->''event_id'',''user_id'',to_jsonb(t)->''user_id'',''guest_session_digest'',to_jsonb(t)->''guest_session_digest'',''event_type'',to_jsonb(t)->''event_type'',''product_id'',to_jsonb(t)->''product_id'',''query_text'',to_jsonb(t)->''query_text'',''occurred_at'',to_jsonb(t)->''occurred_at'',''source_key'',to_jsonb(t)->''source_key'') IS NOT DISTINCT FROM $2 RETURNING to_jsonb(t)' INTO stored USING j,old_j;
ELSE EXECUTE 'DELETE FROM public.interaction_events t USING jsonb_populate_record(NULL::og_compat.interaction_events,$1) r WHERE t.event_id=r.event_id AND t.record_type=''interaction_events'' AND jsonb_build_object(''event_id'',to_jsonb(t)->''event_id'',''user_id'',to_jsonb(t)->''user_id'',''guest_session_digest'',to_jsonb(t)->''guest_session_digest'',''event_type'',to_jsonb(t)->''event_type'',''product_id'',to_jsonb(t)->''product_id'',''query_text'',to_jsonb(t)->''query_text'',''occurred_at'',to_jsonb(t)->''occurred_at'',''source_key'',to_jsonb(t)->''source_key'') IS NOT DISTINCT FROM $1 RETURNING to_jsonb(t)' INTO stored USING old_j; END IF;
IF stored IS NULL THEN RETURN NULL; END IF;
IF TG_OP='DELETE' THEN RETURN OLD; END IF;
result:=jsonb_build_object('event_id',stored->'event_id','user_id',stored->'user_id','guest_session_digest',stored->'guest_session_digest','event_type',stored->'event_type','product_id',stored->'product_id','query_text',stored->'query_text','occurred_at',stored->'occurred_at','source_key',stored->'source_key');
RETURN jsonb_populate_record(NEW,result);
 ELSE RAISE EXCEPTION 'Unknown compatibility view'; END CASE;
END $_$;


--
-- Name: og_apply_case_decision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_apply_case_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE r og_compat.case_rounds; c og_compat.cases; o og_compat.orders;
BEGIN
    NEW.decided_at:=clock_timestamp();
    IF NEW.supersedes_decision_id IS NOT NULL OR (NEW.outcome<>'SELLER_DECLINED' AND NOT NEW.is_final) THEN
        RAISE EXCEPTION 'Final decisions retained; reopening needs a separate authorized round' USING ERRCODE='23514';
    END IF;
    SELECT * INTO STRICT r FROM og_compat.case_rounds WHERE round_id=NEW.round_id FOR UPDATE;
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=r.case_id FOR UPDATE;
    IF r.state<>'OPEN' AND NEW.supersedes_decision_id IS NULL THEN
        RAISE EXCEPTION 'Case round already decided' USING ERRCODE='23514';
    END IF;
    IF c.order_id IS NOT NULL THEN SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=c.order_id FOR UPDATE; END IF;
    IF r.stage='RETURN_APPROVAL' THEN
        IF NEW.actor_type<>'USER' OR NEW.outcome NOT IN ('APPROVE_RETURN','REJECT_RETURN','SELLER_DECLINED')
            OR NOT (og_has_role(NEW.reviewed_by,'KTV') OR
                (NEW.reviewed_by=o.seller_id AND NEW.outcome IN ('APPROVE_RETURN','SELLER_DECLINED'))) THEN
            RAISE EXCEPTION 'Return approval authority/outcome mismatch' USING ERRCODE='23514';
        END IF;
        IF NEW.outcome='APPROVE_RETURN' THEN
            UPDATE og_compat.cases SET state='RETURN_APPROVED',approved_at=NEW.decided_at WHERE case_id=c.case_id;
        ELSIF NEW.outcome='REJECT_RETURN' THEN
            UPDATE og_compat.cases SET state='REJECTED',closed_at=NEW.decided_at WHERE case_id=c.case_id;
        END IF;
    ELSIF r.stage='POST_RETURN_RESOLUTION' THEN
        IF c.valid_returned_at IS NULL OR NEW.outcome NOT IN ('FULL_GOODS_REFUND','EXEMPT_GOODS_REFUND') THEN
            RAISE EXCEPTION 'Post-return decision needs valid returned delivery' USING ERRCODE='23514';
        END IF;
        IF NEW.outcome='EXEMPT_GOODS_REFUND' AND (NEW.actor_type<>'USER' OR NOT og_has_role(NEW.reviewed_by,'KTV')
            OR r.valid_damage_request_at IS NULL) THEN
            RAISE EXCEPTION 'Only KTV may grant exemption after valid request' USING ERRCODE='23514';
        END IF;
        IF NEW.actor_type='SYSTEM_TIMEOUT' AND (NEW.outcome<>'FULL_GOODS_REFUND'
            OR NEW.decided_at<c.seller_response_due_at OR r.valid_damage_request_at IS NOT NULL) THEN
            RAISE EXCEPTION 'Auto refund blocked by deadline/request' USING ERRCODE='23514';
        END IF;
        IF NEW.actor_type='USER' AND NOT (og_has_role(NEW.reviewed_by,'KTV')
            OR (NEW.reviewed_by=o.seller_id AND NEW.outcome='FULL_GOODS_REFUND')) THEN
            RAISE EXCEPTION 'Post-return decision authority mismatch' USING ERRCODE='23514';
        END IF;
        NEW.goods_refund_amount:=CASE WHEN NEW.outcome='FULL_GOODS_REFUND'
            THEN o.subtotal-o.voucher_discount_amount-o.points_discount_amount ELSE 0 END;
        UPDATE og_compat.cases SET state='CLOSED',closed_at=NEW.decided_at WHERE case_id=c.case_id;
    ELSE
        IF NEW.outcome<>'SYSTEM_RESOLVED' OR NEW.actor_type<>'USER' OR
            NOT (og_has_role(NEW.reviewed_by,'KTV') OR og_has_role(NEW.reviewed_by,'ADMIN')) THEN
            RAISE EXCEPTION 'System issue authority mismatch' USING ERRCODE='23514';
        END IF;
        UPDATE og_compat.cases SET state='CLOSED',closed_at=NEW.decided_at WHERE case_id=c.case_id;
    END IF;
    IF NEW.is_final THEN UPDATE og_compat.case_rounds SET state='DECIDED' WHERE round_id=r.round_id; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_apply_ekyc_decision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_apply_ekyc_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE p og_compat.ekyc_profiles;
BEGIN
    NEW.decided_at:=clock_timestamp();
    SELECT * INTO STRICT p FROM og_compat.ekyc_profiles WHERE profile_id=NEW.profile_id FOR UPDATE;
    IF p.state<>'PENDING' OR NOT og_has_role(NEW.reviewed_by,'KTV') THEN
        RAISE EXCEPTION 'Only KTV can decide a pending eKYC revision' USING ERRCODE='23514';
    END IF;
    IF NEW.outcome='VERIFIED' AND (
        p.document_digest IS NULL
        OR (SELECT count(DISTINCT asset_type) FROM og_compat.ekyc_private_assets
            WHERE profile_id=p.profile_id AND deleted_at IS NULL AND expires_at>NEW.decided_at
              AND asset_type IN ('CARD_FRONT','CARD_BACK','LIVE_FRAME','REFERENCE')) <> 4) THEN
        RAISE EXCEPTION 'eKYC identity/private evidence incomplete' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.ekyc_profiles SET state=NEW.outcome,
        verified_at=CASE WHEN NEW.outcome='VERIFIED' THEN NEW.decided_at END,
        reference_expires_at=CASE WHEN NEW.outcome='VERIFIED' THEN
            LEAST(NEW.decided_at+INTERVAL '3 months',
                (SELECT min(expires_at) FROM og_compat.ekyc_private_assets WHERE profile_id=p.profile_id AND deleted_at IS NULL)) END,
        version=version+1 WHERE profile_id=p.profile_id;
    RETURN NEW;
END;
$$;


--
-- Name: og_apply_reward_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_apply_reward_entry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE b BIGINT;
BEGIN
    SELECT balance INTO STRICT b FROM og_compat.reward_accounts WHERE user_id=NEW.user_id FOR UPDATE;
    IF b+NEW.points_delta<0 OR (NEW.entry_type='CREDIT_COMPLETION' AND NOT EXISTS(
        SELECT 1 FROM og_compat.orders WHERE order_id=NEW.order_id AND status='COMPLETED'
            AND NEW.user_id IN (buyer_id,seller_id)))
        OR (NEW.entry_type='CORRECTION' AND NOT og_has_role(NEW.actor_id,'ADMIN')) THEN
        RAISE EXCEPTION 'Reward source/balance not eligible' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.reward_accounts SET balance=balance+NEW.points_delta,version=version+1 WHERE user_id=NEW.user_id;
    RETURN NEW;
END;
$$;


--
-- Name: og_apply_seller_decision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_apply_seller_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE p og_compat.seller_profiles;
BEGIN
    NEW.decided_at:=clock_timestamp();
    SELECT * INTO STRICT p FROM og_compat.seller_profiles WHERE seller_profile_id=NEW.seller_profile_id FOR UPDATE;
    IF p.state<>'PENDING_REVIEW' OR p.revision_no<>NEW.revision_no OR NOT og_has_role(NEW.reviewed_by,'KTV') THEN
        RAISE EXCEPTION 'Only KTV can decide current seller profile' USING ERRCODE='23514';
    END IF;
    IF NEW.outcome='APPROVED' AND (p.pickup_address_id IS NULL
        OR NOT (p.bank_snapshot ?& ARRAY['bank_name','account_number','account_holder'])
        OR NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles e JOIN og_compat.ekyc_decisions d USING(profile_id)
                       WHERE e.profile_id=p.ekyc_profile_id AND e.state='VERIFIED' AND d.outcome='VERIFIED'
                         AND e.reference_expires_at>NEW.decided_at)) THEN
        RAISE EXCEPTION 'Seller prerequisites incomplete' USING ERRCODE='23514';
    END IF;
    NEW.profile_snapshot := to_jsonb(p);
    UPDATE og_compat.seller_profiles SET state=NEW.outcome,updated_at=NEW.decided_at WHERE seller_profile_id=p.seller_profile_id;
    IF NEW.outcome='APPROVED' THEN
        INSERT INTO og_compat.user_roles(user_id,role_id,granted_by)
            SELECT p.user_id,r.role_id,NEW.reviewed_by FROM og_compat.roles r WHERE r.role_name='SELLER' AND NOT EXISTS(SELECT 1 FROM og_compat.user_roles ur WHERE ur.user_id=p.user_id AND ur.role_id=r.role_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_case_settlement_allowed(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_case_settlement_allowed(p_decision bigint, p_order bigint, p_cause text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', '$user', 'public'
    AS $$
    SELECT EXISTS(SELECT 1 FROM og_compat.case_decisions d JOIN og_compat.case_rounds r USING(round_id) JOIN og_compat.cases c USING(case_id)
        WHERE d.decision_id=p_decision AND c.order_id=p_order AND c.case_type='RETURN'
          AND c.valid_returned_at IS NOT NULL AND d.is_final
          AND ((p_cause='RETURN' AND d.outcome='FULL_GOODS_REFUND')
            OR (p_cause='EXEMPTION' AND d.outcome='EXEMPT_GOODS_REFUND')))
$$;


--
-- Name: og_close_case_holds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_close_case_holds() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    UPDATE og_compat.money_holds SET closed_at=clock_timestamp() WHERE case_id=(SELECT r.case_id FROM og_compat.case_rounds r
        WHERE r.round_id=NEW.round_id) AND closed_at IS NULL AND EXISTS(SELECT 1 FROM og_compat.cases c
        WHERE c.case_id=og_compat.money_holds.case_id AND c.state IN ('CLOSED','REJECTED'));
    RETURN NEW;
END;
$$;


--
-- Name: og_compute_listing_assessment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_compute_listing_assessment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE r og_compat.product_revisions; f og_compat.listing_fee_policies;
BEGIN
    PERFORM 1 FROM og_compat.products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT * INTO STRICT r FROM og_compat.product_revisions WHERE revision_id=NEW.revision_id;
    IF r.state<>'SUBMITTED' OR r.provenance<>'UC83' OR NOT EXISTS (
        SELECT 1 FROM og_compat.product_moderation_decisions WHERE decision_id=NEW.decision_id
            AND revision_id=r.revision_id AND decision='APPROVED') THEN
        RAISE EXCEPTION 'Fee requires approval of this revision' USING ERRCODE='23514';
    END IF;
    IF EXISTS(SELECT 1 FROM og_compat.listing_fee_charges c JOIN og_compat.listing_fee_assessments a USING(assessment_id)
              WHERE a.product_id=NEW.product_id AND c.state IN ('PENDING','RECONCILIATION')) THEN
        RAISE EXCEPTION 'Listing has an unresolved fee charge' USING ERRCODE='23514';
    END IF;
    NEW.assessed_at := clock_timestamp();
    SELECT * INTO STRICT f FROM og_compat.listing_fee_policies WHERE policy_id=NEW.policy_id
        AND effective_from<=NEW.assessed_at AND (effective_until IS NULL OR effective_until>NEW.assessed_at);
    NEW.listed_total := r.listed_unit_price*r.quantity;
    SELECT listed_total INTO NEW.previous_approved_total FROM og_compat.listing_fee_assessments
        WHERE product_id=NEW.product_id ORDER BY assessment_id DESC LIMIT 1;
    SELECT COALESCE(sum(receipt.amount),0) INTO NEW.cumulative_before FROM og_compat.listing_fee_receipts receipt
        JOIN og_compat.listing_fee_charges c USING(charge_id) JOIN og_compat.listing_fee_assessments a USING(assessment_id)
        WHERE a.product_id=NEW.product_id;
    NEW.computed_fee := CASE WHEN NEW.listed_total<f.threshold_amount THEN f.fixed_below
        ELSE round(NEW.listed_total*f.rate_at_or_above,0) END;
    NEW.amount_due := CASE WHEN NEW.previous_approved_total IS NULL
        OR NEW.listed_total>NEW.previous_approved_total
        THEN greatest(0,NEW.computed_fee-NEW.cumulative_before) ELSE 0 END;
    RETURN NEW;
END;
$$;


--
-- Name: og_confirm_direct_handover(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_confirm_direct_handover(p_shipment bigint) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE s og_compat.shipments; delivered TIMESTAMPTZ;
BEGIN
    PERFORM 1 FROM og_compat.orders WHERE order_id=(SELECT order_id FROM og_compat.shipments WHERE shipment_id=p_shipment) FOR UPDATE;
    SELECT * INTO STRICT s FROM og_compat.shipments WHERE shipment_id=p_shipment FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.delivery_method='CARRIER' THEN
        RAISE EXCEPTION 'Direct handover only' USING ERRCODE='23514'; END IF;
    IF s.valid_delivery_at IS NOT NULL THEN RETURN TRUE; END IF;
    IF EXISTS(SELECT 1 FROM og_compat.handover_confirmations WHERE shipment_id=p_shipment AND outcome='FAILED') THEN RETURN FALSE; END IF;
    IF s.otp_consumed_at IS NOT NULL THEN delivered:=s.otp_consumed_at;
    ELSIF (SELECT count(*) FROM og_compat.handover_confirmations WHERE shipment_id=p_shipment AND outcome='SUCCESS')=2 THEN
        SELECT max(confirmed_at) INTO delivered FROM og_compat.handover_confirmations WHERE shipment_id=p_shipment;
    ELSE RETURN FALSE; END IF;
    UPDATE og_compat.shipments SET valid_delivery_at=delivered,status='DELIVERED',shipped_at=COALESCE(shipped_at,initiated_at),
        delivered_at=delivered WHERE shipment_id=p_shipment;
    IF s.leg='RETURN' THEN
        UPDATE og_compat.cases SET state='POST_RETURN',valid_returned_at=delivered,seller_response_due_at=delivered+INTERVAL '2 days'
            WHERE case_id=s.return_case_id;
    ELSIF s.leg='OUTBOUND' THEN
        UPDATE og_compat.orders SET status='DELIVERED',valid_delivered_at=delivered,
            return_due_at=CASE WHEN return_allowed THEN delivered+INTERVAL '3 days' END WHERE order_id=s.order_id;
    END IF;
    RETURN TRUE;
END;
$$;


--
-- Name: og_confirm_listing_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_confirm_listing_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.listing_fee_charges; p BIGINT;
BEGIN
    SELECT product_id INTO STRICT p FROM og_compat.listing_fee_assessments a JOIN og_compat.listing_fee_charges ch USING(assessment_id)
        WHERE ch.charge_id=NEW.charge_id;
    PERFORM 1 FROM og_compat.products WHERE product_id=p FOR UPDATE;
    SELECT * INTO STRICT c FROM og_compat.listing_fee_charges WHERE charge_id=NEW.charge_id FOR UPDATE;
    IF c.state<>'PENDING' OR NEW.amount<>c.amount THEN
        RAISE EXCEPTION 'Listing fee amount/state mismatch; reconciliation required' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.listing_fee_charges SET state='CONFIRMED' WHERE charge_id=NEW.charge_id;
    RETURN NEW;
END;
$$;


--
-- Name: og_confirm_zero_checkout(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_confirm_zero_checkout() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE g og_compat.checkout_groups;
BEGIN
    SELECT * INTO STRICT g FROM og_compat.checkout_groups WHERE group_id=NEW.group_id FOR UPDATE;
    NEW.confirmed_at:=clock_timestamp();
    IF g.expected_total<>0 OR g.state<>'READY' OR NEW.confirmed_at>=g.payment_due_at
        OR NOT EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=g.group_id)
        OR EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=g.group_id AND (total_amount<>0 OR status<>'PAYMENT_PENDING'))
        OR EXISTS(SELECT 1 FROM og_compat.payment_intents WHERE group_id=g.group_id) THEN
        RAISE EXCEPTION 'Zero checkout needs an in-time, unpaid, fully subsidized group' USING ERRCODE='23514';
    END IF;
    UPDATE og_compat.orders SET status='PAID_HELD',paid_confirmed_at=NEW.confirmed_at,
        seller_accept_due_at=NEW.confirmed_at+INTERVAL '2 days' WHERE group_id=g.group_id;
    UPDATE og_compat.inventory_reservations r SET state='FUNDED' FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id)
        WHERE r.order_item_id=i.order_item_id AND o.group_id=g.group_id AND r.state='HELD';
    UPDATE og_compat.checkout_groups SET state='PAID' WHERE group_id=g.group_id;
    RETURN NEW;
END;
$$;


--
-- Name: og_consume_auth_challenge(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_consume_auth_challenge(p_challenge uuid, p_digest text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.auth_challenges;
BEGIN
    SELECT * INTO STRICT c FROM og_compat.auth_challenges WHERE challenge_id=p_challenge FOR UPDATE;
    IF c.state<>'OPEN' OR c.expires_at<=clock_timestamp() OR c.attempt_count>=c.max_attempts THEN RETURN FALSE; END IF;
    UPDATE og_compat.auth_challenges SET attempt_count=attempt_count+1,
        state=CASE WHEN code_digest=p_digest THEN 'CONSUMED' ELSE 'OPEN' END,
        consumed_at=CASE WHEN code_digest=p_digest THEN clock_timestamp() END WHERE challenge_id=c.challenge_id;
    RETURN c.code_digest=p_digest;
END;
$$;


--
-- Name: og_consume_handover_otp(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_consume_handover_otp(p_shipment bigint, p_buyer bigint, p_digest text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE s og_compat.shipments;
BEGIN
    PERFORM 1 FROM og_compat.orders WHERE order_id=(SELECT order_id FROM og_compat.shipments WHERE shipment_id=p_shipment) FOR UPDATE;
    SELECT * INTO STRICT s FROM og_compat.shipments WHERE shipment_id=p_shipment FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.delivery_method='CARRIER' OR NOT EXISTS(SELECT 1 FROM og_compat.orders
        WHERE order_id=s.order_id AND buyer_id=p_buyer) OR s.otp_digest IS NULL OR s.otp_consumed_at IS NOT NULL
        OR s.otp_expires_at<=clock_timestamp() OR s.otp_attempt_count>=5 THEN RETURN FALSE; END IF;
    UPDATE og_compat.shipments SET otp_attempt_count=otp_attempt_count+1,
        otp_consumed_at=CASE WHEN otp_digest=p_digest THEN clock_timestamp() END WHERE shipment_id=p_shipment;
    IF s.otp_digest<>p_digest THEN RETURN FALSE; END IF;
    RETURN og_confirm_direct_handover(p_shipment);
END;
$$;


--
-- Name: og_early_complete_order(bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_early_complete_order(p_order bigint, p_buyer bigint, p_warning text, p_command text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders;
BEGIN
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=p_order FOR UPDATE;
    IF EXISTS(SELECT 1 FROM og_compat.order_events WHERE command_key=p_command AND order_id=p_order AND actor_id=p_buyer
        AND event_type='EARLY_COMPLETION_ACCEPTED') THEN RETURN TRUE; END IF;
    IF o.workflow_model<>'UC83' OR o.buyer_id<>p_buyer OR o.valid_delivered_at IS NULL
        OR NULLIF(btrim(p_warning),'') IS NULL OR o.status<>'DELIVERED' OR og_order_has_blocking_case(p_order)
        OR EXISTS(SELECT 1 FROM og_compat.money_holds h JOIN og_compat.order_fund_components c USING(component_id)
            WHERE c.order_id=p_order AND h.closed_at IS NULL) THEN
        RAISE EXCEPTION 'Early completion needs Buyer warning consent and no blockers' USING ERRCODE='23514'; END IF;
    UPDATE og_compat.orders SET early_completed_at=clock_timestamp(),early_completion_warning_version=p_warning WHERE order_id=p_order;
    INSERT INTO og_compat.order_events(event_id,order_id,actor_id,event_type,metadata,command_key)
        VALUES(gen_random_uuid(),p_order,p_buyer,'EARLY_COMPLETION_ACCEPTED',jsonb_build_object('warning_version',p_warning),p_command);
    RETURN TRUE;
END;
$$;


--
-- Name: og_guard_account_restriction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_account_restriction() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    PERFORM 1 FROM og_compat.users WHERE user_id=NEW.user_id FOR UPDATE;
    IF NOT (og_has_role(NEW.imposed_by,'KTV') OR og_has_role(NEW.imposed_by,'ADMIN')) THEN
        RAISE EXCEPTION 'Restriction needs KTV/Admin authority' USING ERRCODE='23514';
    END IF;
    IF NEW.scope='LOGIN' AND NEW.closed_at IS NULL AND (
        EXISTS(SELECT 1 FROM og_compat.orders o WHERE NEW.user_id IN (o.buyer_id,o.seller_id)
            AND o.status NOT IN ('COMPLETED','CANCELLED','REFUNDED'))
        OR EXISTS(SELECT 1 FROM og_compat.cases c LEFT JOIN og_compat.orders o USING(order_id)
            WHERE c.state NOT IN ('CLOSED','REJECTED')
                AND NEW.user_id IN (c.created_by,o.buyer_id,o.seller_id))) THEN
        RAISE EXCEPTION 'Open obligations require login access; restrict new transactions instead' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_admin_dispatch(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_admin_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NOT og_has_role(NEW.sender_id,'ADMIN') THEN
        RAISE EXCEPTION 'Only Admin sends manual dispatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_auth_challenge_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_auth_challenge_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' OR ROW(NEW.challenge_id,NEW.user_id,NEW.subject_key,NEW.purpose,NEW.code_digest,
        NEW.issued_at,NEW.expires_at,NEW.next_send_at,NEW.max_attempts,NEW.command_key) IS DISTINCT FROM
        ROW(OLD.challenge_id,OLD.user_id,OLD.subject_key,OLD.purpose,OLD.code_digest,OLD.issued_at,
        OLD.expires_at,OLD.next_send_at,OLD.max_attempts,OLD.command_key)
        OR OLD.state<>'OPEN' OR NEW.attempt_count<OLD.attempt_count
        OR (NEW.state='CONSUMED' AND (NEW.attempt_count<>OLD.attempt_count+1
            OR OLD.attempt_count>=OLD.max_attempts OR clock_timestamp()>=OLD.expires_at
            OR NEW.consumed_at<OLD.issued_at OR NEW.consumed_at>=OLD.expires_at)) THEN
        RAISE EXCEPTION 'Challenge deadline/digest/consumption history retained' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_canonical_moderation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_canonical_moderation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NEW.revision_id IS NOT NULL AND (
        NOT og_has_role(NEW.reviewer_id,'KTV') OR NOT EXISTS (
            SELECT 1 FROM og_compat.product_revisions r JOIN og_compat.products p USING(product_id)
            WHERE r.revision_id=NEW.revision_id AND r.state='SUBMITTED' AND r.provenance='UC83'
              AND p.current_revision_id=r.revision_id AND p.status='PENDING')) THEN
        RAISE EXCEPTION 'KTV must review the current submitted revision' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_case_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_case_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.cases; o og_compat.orders;
BEGIN
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.case_id FOR UPDATE;
    NEW.occurred_at:=clock_timestamp();
    IF NEW.event_type='ESCALATED' AND (NOT og_has_role(NEW.actor_id,'KTV') OR
        NOT og_has_role(NEW.recipient_id,'ADMIN')) THEN
        RAISE EXCEPTION 'Escalation needs KTV to Admin' USING ERRCODE='23514';
    END IF;
    IF NEW.event_type='VALID_DAMAGE_REQUEST' THEN
        SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=c.order_id;
        IF NEW.actor_id<>o.seller_id OR c.valid_returned_at IS NULL OR NEW.occurred_at>c.seller_response_due_at
            OR NOT EXISTS(SELECT 1 FROM og_compat.case_rounds WHERE round_id=NEW.round_id
                AND stage='POST_RETURN_RESOLUTION' AND state='OPEN')
            OR NOT EXISTS(SELECT 1 FROM og_compat.case_evidence WHERE round_id=NEW.round_id AND submitted_by=NEW.actor_id) THEN
            RAISE EXCEPTION 'Only complete in-time Seller request blocks auto refund' USING ERRCODE='23514';
        END IF;
        UPDATE og_compat.case_rounds SET valid_damage_request_at=NEW.occurred_at WHERE round_id=NEW.round_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_case_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_case_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE r og_compat.case_rounds; c og_compat.cases; o og_compat.orders; n INTEGER;
BEGIN
    SELECT * INTO STRICT r FROM og_compat.case_rounds WHERE round_id=NEW.round_id FOR UPDATE;
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=r.case_id;
    IF r.state<>'OPEN' THEN RAISE EXCEPTION 'Evidence round closed' USING ERRCODE='23514'; END IF;
    NEW.submitted_at:=clock_timestamp();
    IF c.order_id IS NOT NULL THEN
        SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=c.order_id;
        IF NEW.submitted_by NOT IN (o.buyer_id,o.seller_id) AND NOT og_has_role(NEW.submitted_by,'KTV') THEN
            RAISE EXCEPTION 'Evidence author not a party/KTV' USING ERRCODE='23514';
        END IF;
        IF NEW.submitted_by=o.buyer_id AND c.case_type='RETURN'
            AND NEW.submitted_at>o.valid_delivered_at+INTERVAL '3 days' THEN
            RAISE EXCEPTION 'Buyer evidence submission deadline passed' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.submitted_by<>c.created_by AND NOT og_has_role(NEW.submitted_by,'KTV') THEN
        RAISE EXCEPTION 'Private system issue evidence author invalid' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO n FROM og_compat.case_evidence WHERE round_id=NEW.round_id
        AND submitted_by=NEW.submitted_by AND submission_no=NEW.submission_no AND media_type=NEW.media_type;
    IF (NEW.media_type='IMAGE' AND n>=5) OR (NEW.media_type='VIDEO' AND n>=2) THEN
        RAISE EXCEPTION 'Evidence submission media limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_case_round(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_case_round() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.cases;
BEGIN
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.case_id FOR UPDATE;
    IF (c.case_type='SYSTEM_ISSUE')<>(NEW.stage='SYSTEM_REVIEW') OR
        (NEW.stage='POST_RETURN_RESOLUTION' AND c.valid_returned_at IS NULL) THEN
        RAISE EXCEPTION 'Case round stage incompatible with case/delivery' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_checkout_item(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_checkout_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders; p og_compat.products; r og_compat.product_revisions;
BEGIN
    IF TG_OP='DELETE' THEN
        IF OLD.workflow_model='UC83' THEN RAISE EXCEPTION 'Order item history retained' USING ERRCODE='23514'; END IF;
        RETURN OLD;
    END IF;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id;
    IF NEW.workflow_model<>o.workflow_model THEN RAISE EXCEPTION 'Item workflow mismatch' USING ERRCODE='23514'; END IF;
    IF NEW.workflow_model='UC83' THEN
        SELECT * INTO STRICT p FROM og_compat.products WHERE product_id=NEW.product_id;
        SELECT * INTO STRICT r FROM og_compat.product_revisions WHERE revision_id=NEW.product_revision_id;
        IF p.seller_id<>o.seller_id OR NEW.return_allowed IS DISTINCT FROM o.return_allowed
           OR NEW.return_allowed IS DISTINCT FROM r.return_allowed OR NEW.listed_price<>r.listed_unit_price
           OR NOT (r.delivery_options ? o.delivery_method) THEN
            RAISE EXCEPTION 'Seller/return/delivery/price snapshot mismatch' USING ERRCODE='23514';
        END IF;
        IF NEW.accepted_offer_id IS NOT NULL AND NOT EXISTS(
            SELECT 1 FROM og_compat.offers offer JOIN og_compat.conversations c USING(conversation_id)
            WHERE offer.offer_id=NEW.accepted_offer_id AND offer.status='ACCEPTED'
              AND c.buyer_id=o.buyer_id AND c.seller_id=o.seller_id AND c.product_id=NEW.product_id
              AND offer.offered_item_price=NEW.agreed_price) THEN
            RAISE EXCEPTION 'Accepted offer belongs to another transaction' USING ERRCODE='23514';
        END IF;
        IF TG_OP='UPDATE' AND NEW IS DISTINCT FROM OLD THEN
            RAISE EXCEPTION 'UC83 order item snapshot is immutable' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_checkout_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_checkout_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME='checkout_groups' THEN
        IF TG_OP='DELETE' OR (to_jsonb(NEW)-'state') IS DISTINCT FROM (to_jsonb(OLD)-'state') THEN
            RAISE EXCEPTION 'Checkout command, amount and deadline are immutable' USING ERRCODE='23514'; END IF;
    ELSIF OLD.workflow_model='UC83' AND (TG_OP='DELETE' OR
        ROW(NEW.workflow_model,NEW.group_id,NEW.checkout_group_id,NEW.buyer_id,NEW.seller_id,NEW.subtotal,
            NEW.shipping_fee,NEW.total_amount,NEW.voucher_discount_amount,NEW.shipping_discount_amount,
            NEW.points_discount_amount,NEW.return_allowed,NEW.delivery_method,NEW.carrier_snapshot,NEW.handover_day,
            NEW.payment_due_at,NEW.created_at,NEW.shipping_recipient_name,NEW.shipping_phone_number,NEW.shipping_province,
            NEW.shipping_district,NEW.shipping_ward,NEW.shipping_detail_address)
        IS DISTINCT FROM ROW(OLD.workflow_model,OLD.group_id,OLD.checkout_group_id,OLD.buyer_id,OLD.seller_id,OLD.subtotal,
            OLD.shipping_fee,OLD.total_amount,OLD.voucher_discount_amount,OLD.shipping_discount_amount,
            OLD.points_discount_amount,OLD.return_allowed,OLD.delivery_method,OLD.carrier_snapshot,OLD.handover_day,
            OLD.payment_due_at,OLD.created_at,OLD.shipping_recipient_name,OLD.shipping_phone_number,OLD.shipping_province,
            OLD.shipping_district,OLD.shipping_ward,OLD.shipping_detail_address)) THEN
        RAISE EXCEPTION 'UC83 order checkout snapshot retained' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_discount_source(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_discount_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE gid UUID; pid BIGINT;
BEGIN
    SELECT o.group_id,i.product_id INTO STRICT gid,pid FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id)
        WHERE i.order_item_id=NEW.order_item_id AND i.workflow_model='UC83';
    IF NEW.redemption_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.checkout_redemptions c
        JOIN og_compat.voucher_grants g USING(grant_id) JOIN og_compat.voucher_revisions r USING(revision_id)
        WHERE c.redemption_id=NEW.redemption_id AND c.group_id=gid AND r.benefit_component=NEW.component AND (r.scope='CHECKOUT' OR EXISTS(
            SELECT 1 FROM og_compat.voucher_revision_products WHERE revision_id=r.revision_id AND product_id=pid))) THEN
        RAISE EXCEPTION 'Voucher allocation outside checkout/product scope' USING ERRCODE='23514';
    END IF;
    IF NEW.reward_entry_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.reward_ledger
        WHERE entry_id=NEW.reward_entry_id AND group_id=gid AND entry_type='DEBIT_CHECKOUT') THEN
        RAISE EXCEPTION 'Point allocation belongs to another checkout' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_ekyc_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_ekyc_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE p og_compat.ekyc_profiles;
BEGIN
    SELECT * INTO STRICT p FROM og_compat.ekyc_profiles WHERE profile_id=NEW.profile_id FOR UPDATE;
    IF p.state NOT IN ('DRAFT','IN_PROGRESS') THEN
        RAISE EXCEPTION 'eKYC input is closed' USING ERRCODE='23514';
    END IF;
    NEW.attempted_at := clock_timestamp();
    IF NEW.result='MANUAL_REVIEW' AND NOT og_has_role(NEW.fallback_authorized_by,'ADMIN') THEN
        RAISE EXCEPTION 'Manual fallback requires Admin' USING ERRCODE='23514';
    END IF;
    IF NEW.result='NON_MATCH' THEN
        IF p.nonmatch_count >= 15 OR
           (p.last_nonmatch_at IS NOT NULL AND NEW.attempted_at < p.last_nonmatch_at + INTERVAL '3 seconds') THEN
            RAISE EXCEPTION 'eKYC attempt limit/cooldown' USING ERRCODE='23514';
        END IF;
        UPDATE og_compat.ekyc_profiles SET nonmatch_count=nonmatch_count+1,last_nonmatch_at=NEW.attempted_at
            WHERE profile_id=p.profile_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_ekyc_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_ekyc_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND (
        ROW(NEW.profile_id,NEW.user_id,NEW.revision_no,NEW.created_at) IS DISTINCT FROM
        ROW(OLD.profile_id,OLD.user_id,OLD.revision_no,OLD.created_at)
        OR (OLD.state IN ('PENDING','VERIFIED','REJECTED','EXPIRED') AND
            ROW(NEW.submitted_data,NEW.ai_summary,NEW.document_digest,NEW.submitted_at) IS DISTINCT FROM
            ROW(OLD.submitted_data,OLD.ai_summary,OLD.document_digest,OLD.submitted_at))
        OR (OLD.state IN ('VERIFIED','REJECTED','EXPIRED') AND NEW.state<>OLD.state
            AND NOT (OLD.state='VERIFIED' AND NEW.state='EXPIRED')))) THEN
        RAISE EXCEPTION 'eKYC identity/submitted evidence is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_export_authority(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_export_authority() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NOT og_has_role(NEW.requested_by,'ADMIN') THEN RAISE EXCEPTION 'Admin export only' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_fee_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_fee_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF TG_OP='DELETE' OR ROW(NEW.policy_code,NEW.threshold_amount,NEW.fixed_below,NEW.rate_at_or_above,
        NEW.effective_from,NEW.created_by) IS DISTINCT FROM ROW(OLD.policy_code,OLD.threshold_amount,
        OLD.fixed_below,OLD.rate_at_or_above,OLD.effective_from,OLD.created_by)
        OR NEW.effective_until IS NULL OR NEW.effective_until<=clock_timestamp()
        OR EXISTS(SELECT 1 FROM og_compat.listing_fee_assessments WHERE policy_id=OLD.policy_id AND assessed_at>=NEW.effective_until) THEN
        RAISE EXCEPTION 'Keep fee policy history; end policy in the future and create a successor' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_fund_component(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_fund_component() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders; expected NUMERIC;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Fund component history retained' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' THEN
        IF ROW(NEW.component_id,NEW.order_id,NEW.allocation_id,NEW.late_confirmation_id,NEW.component_type,
            NEW.confirmed_amount,NEW.funding_reference,NEW.confirmed_at) IS DISTINCT FROM
            ROW(OLD.component_id,OLD.order_id,OLD.allocation_id,OLD.late_confirmation_id,OLD.component_type,
            OLD.confirmed_amount,OLD.funding_reference,OLD.confirmed_at) OR pg_trigger_depth()<2 THEN
            RAISE EXCEPTION 'Money amount/source immutable; balances change through operations only' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id FOR UPDATE;
    expected:=CASE NEW.component_type
        WHEN 'GOODS_CASH' THEN o.subtotal-o.voucher_discount_amount-o.points_discount_amount
        WHEN 'SHIPPING_CASH' THEN o.shipping_fee-o.shipping_discount_amount
        WHEN 'PLATFORM_GOODS_SUBSIDY' THEN o.voucher_discount_amount+o.points_discount_amount
        WHEN 'PLATFORM_SHIPPING_SUBSIDY' THEN o.shipping_discount_amount
        WHEN 'LATE_PAYMENT_CASH' THEN o.total_amount END;
    IF o.workflow_model<>'UC83' OR NEW.confirmed_amount<>expected
        OR NEW.reserved_amount<>0 OR NEW.refunded_amount<>0 OR NEW.released_amount<>0 OR NEW.version<>0
        OR (NEW.component_type='LATE_PAYMENT_CASH' AND NOT EXISTS(
            SELECT 1 FROM og_compat.payment_confirmations c JOIN og_compat.payment_intents i USING(intent_id)
            WHERE c.confirmation_id=NEW.late_confirmation_id AND c.disposition='RECONCILIATION'
                AND i.group_id=o.group_id))
        OR (NEW.component_type LIKE 'PLATFORM_%' AND o.total_amount>0 AND NOT EXISTS(
            SELECT 1 FROM og_compat.payment_allocations WHERE order_id=o.order_id)) THEN
        RAISE EXCEPTION 'Fund component must equal its confirmed order source' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_grant_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_grant_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' OR ROW(NEW.grant_id,NEW.revision_id,NEW.user_id,NEW.source,NEW.issued_by,NEW.reason,
        NEW.granted_at,NEW.expires_at,NEW.command_key) IS DISTINCT FROM ROW(OLD.grant_id,OLD.revision_id,OLD.user_id,
        OLD.source,OLD.issued_by,OLD.reason,OLD.granted_at,OLD.expires_at,OLD.command_key)
        OR OLD.state<>'AVAILABLE' OR NEW.state NOT IN ('REDEEMED','REVOKED')
        OR (NEW.state='REDEEMED' AND pg_trigger_depth()<2) THEN
        RAISE EXCEPTION 'Voucher ownership/history cannot be restored after use' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_handover_party(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_handover_party() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM og_compat.shipments s JOIN og_compat.orders o USING(order_id)
        WHERE s.shipment_id=NEW.shipment_id AND s.workflow_model='UC83'
          AND s.delivery_method IN ('SELF_PICKUP','SELF_DELIVERY')
          AND NEW.user_id=CASE NEW.party WHEN 'BUYER' THEN o.buyer_id ELSE o.seller_id END) THEN
        RAISE EXCEPTION 'Handover confirmation must belong to correct order party' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_intent_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_intent_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NEW.intent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.payment_intents
        WHERE intent_id=NEW.intent_id AND expected_amount=NEW.amount AND currency=NEW.currency) THEN
        RAISE EXCEPTION 'Attempt amount/currency differs from intent' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_inventory_reservation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_inventory_reservation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE p og_compat.products; o og_compat.orders; i og_compat.order_items; delta INTEGER;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reservation history is retained' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT p FROM og_compat.products WHERE product_id=NEW.product_id FOR UPDATE;
    SELECT * INTO STRICT i FROM og_compat.order_items WHERE order_item_id=NEW.order_item_id;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=i.order_id;
    IF p.workflow_model<>'UC83' OR i.workflow_model<>'UC83' OR o.workflow_model<>'UC83'
       OR NEW.quantity<>i.quantity OR NEW.expires_at<>o.payment_due_at THEN
        RAISE EXCEPTION 'Reservation must match UC83 item and original deadline' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.state<>'HELD' OR p.status<>'ACTIVE' OR p.public_revision_id IS DISTINCT FROM i.product_revision_id OR p.quantity_available<NEW.quantity
           OR p.deleted_at IS NOT NULL OR clock_timestamp()>=NEW.expires_at THEN
            RAISE EXCEPTION 'Product quantity unavailable' USING ERRCODE='23514';
        END IF;
        UPDATE og_compat.products SET quantity_held=quantity_held+NEW.quantity WHERE product_id=p.product_id;
    ELSE
        IF ROW(NEW.product_id,NEW.order_item_id,NEW.quantity,NEW.created_at,NEW.expires_at,NEW.command_key)
           IS DISTINCT FROM ROW(OLD.product_id,OLD.order_item_id,OLD.quantity,OLD.created_at,OLD.expires_at,OLD.command_key) THEN
            RAISE EXCEPTION 'Reservation snapshot is immutable' USING ERRCODE='23514';
        END IF;
        IF NEW.state=OLD.state THEN RETURN NEW; END IF;
        IF NOT ((OLD.state='HELD' AND NEW.state IN ('FUNDED','RELEASED'))
            OR (OLD.state='FUNDED' AND NEW.state IN ('CONSUMED','RELEASED'))) THEN
            RAISE EXCEPTION 'Invalid reservation transition' USING ERRCODE='23514';
        END IF;
        IF NEW.state='FUNDED' AND (o.paid_confirmed_at IS NULL OR o.paid_confirmed_at>OLD.expires_at
            OR o.status='CANCELLED') THEN
            RAISE EXCEPTION 'Late payment cannot fund cancelled/expired reservation' USING ERRCODE='23514';
        END IF;
        IF NEW.state='CONSUMED' AND (o.status<>'SELLER_CONFIRMED' OR o.seller_accept_due_at IS NULL
            OR clock_timestamp()>o.seller_accept_due_at) THEN
            RAISE EXCEPTION 'Seller acceptance is not eligible' USING ERRCODE='23514';
        END IF;
        IF NEW.state IN ('RELEASED','CONSUMED') THEN
            delta := CASE WHEN NEW.state='CONSUMED' THEN NEW.quantity ELSE 0 END;
            UPDATE og_compat.products SET quantity_held=quantity_held-NEW.quantity,quantity_sold=quantity_sold+delta,
                status=CASE WHEN quantity_sold+delta=quantity_total THEN 'SOLD' ELSE status END
                WHERE product_id=p.product_id;
        END IF;
        NEW.changed_at:=clock_timestamp();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_listing_activation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_listing_activation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NEW.workflow_model='UC83' AND NEW.status='ACTIVE' THEN
        IF NEW.current_revision_id IS DISTINCT FROM NEW.public_revision_id OR NOT EXISTS (
            SELECT 1 FROM og_compat.product_revisions r JOIN og_compat.listing_fee_assessments a USING(revision_id)
            WHERE r.revision_id=NEW.public_revision_id AND r.product_id=NEW.product_id AND r.provenance='UC83'
              AND r.listed_unit_price=NEW.listed_price AND r.quantity=NEW.quantity_total
              AND r.return_allowed IS NOT DISTINCT FROM NEW.return_allowed
              AND r.delivery_options=NEW.delivery_options
              AND (a.amount_due=0 OR EXISTS(SELECT 1 FROM og_compat.listing_fee_receipts receipt
                  JOIN og_compat.listing_fee_charges c USING(charge_id) WHERE c.assessment_id=a.assessment_id))
        ) OR NOT EXISTS(SELECT 1 FROM og_compat.seller_profiles s JOIN og_compat.seller_profile_decisions d USING(seller_profile_id)
            WHERE s.user_id=NEW.seller_id AND s.state='APPROVED' AND d.revision_no=s.revision_no
              AND d.outcome='APPROVED') OR NOT og_has_role(NEW.seller_id,'SELLER') THEN
            RAISE EXCEPTION 'ACTIVE requires current KTV approval, confirmed listing fee and seller approval'
                USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_listing_charge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_listing_charge() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM og_compat.listing_fee_assessments WHERE assessment_id=NEW.assessment_id
        AND amount_due=NEW.amount AND amount_due>0) THEN
        RAISE EXCEPTION 'Listing fee charge must equal positive assessment due' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND (NEW.assessment_id<>OLD.assessment_id OR NEW.amount<>OLD.amount
        OR (OLD.state='CONFIRMED' AND NEW IS DISTINCT FROM OLD)) THEN
        RAISE EXCEPTION 'Confirmed listing charge is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_manual_recipient(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_manual_recipient() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE d og_compat.notification_dispatches;
BEGIN
    IF NEW.dispatch_id IS NOT NULL THEN
        SELECT * INTO STRICT d FROM og_compat.notification_dispatches WHERE dispatch_id=NEW.dispatch_id;
        IF NOT (og_has_role(NEW.user_id,'BUYER') OR og_has_role(NEW.user_id,'SELLER') OR og_has_role(NEW.user_id,'KTV')) THEN
            RAISE EXCEPTION 'Manual recipient must be Buyer/Seller/KTV' USING ERRCODE='23514';
        END IF;
        NEW.sender_id:=d.sender_id; NEW.event_id:=d.event_id; NEW.title:=d.title; NEW.content:=d.content;
        NEW.target_data:=d.target_data;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_new_transaction(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_new_transaction() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders;
BEGIN
    SELECT o1.* INTO STRICT o FROM og_compat.order_items i JOIN og_compat.orders o1 USING(order_id) WHERE i.order_item_id=NEW.order_item_id;
    PERFORM 1 FROM og_compat.users WHERE user_id IN (o.buyer_id,o.seller_id) ORDER BY user_id FOR UPDATE;
    IF NOT og_has_role(o.buyer_id,'BUYER') OR NOT og_has_role(o.seller_id,'SELLER')
        OR EXISTS(SELECT 1 FROM og_compat.account_restrictions WHERE user_id IN (o.buyer_id,o.seller_id) AND closed_at IS NULL)
        OR EXISTS(SELECT 1 FROM og_compat.seller_buyer_blocks WHERE seller_id=o.seller_id AND buyer_id=o.buyer_id AND unblocked_at IS NULL)
        OR NOT EXISTS(SELECT 1 FROM og_compat.seller_profiles s JOIN og_compat.ekyc_profiles e ON e.profile_id=s.ekyc_profile_id
            JOIN og_compat.ekyc_decisions d ON d.profile_id=e.profile_id WHERE s.user_id=o.seller_id AND s.state='APPROVED'
                AND e.state='VERIFIED' AND d.outcome='VERIFIED' AND e.reference_expires_at>clock_timestamp())
        OR EXISTS(SELECT 1 FROM og_compat.ekyc_profiles WHERE user_id=o.seller_id AND state IN ('DRAFT','IN_PROGRESS','PENDING')) THEN
        RAISE EXCEPTION 'New transaction blocked by identity/restriction/party block' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_payment_allocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_payment_allocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    PERFORM 1 FROM og_compat.payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF NOT EXISTS(SELECT 1 FROM og_compat.payment_intents i JOIN og_compat.payment_confirmations c USING(intent_id)
        JOIN og_compat.orders o ON o.group_id=i.group_id WHERE i.intent_id=NEW.intent_id AND i.purpose='CHECKOUT_GROUP'
          AND c.confirmation_id=NEW.confirmation_id AND c.disposition='ALLOCATABLE'
          AND o.order_id=NEW.order_id AND o.total_amount=NEW.amount AND o.status='PAYMENT_PENDING') THEN
        RAISE EXCEPTION 'Allocation does not belong to eligible order/confirmed group' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_payment_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_payment_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE i og_compat.payment_intents;
BEGIN
    SELECT * INTO STRICT i FROM og_compat.payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF NEW.amount<>i.expected_amount OR NEW.provider<>i.payment_method OR NOT EXISTS(SELECT 1 FROM og_compat.payment_attempts
        WHERE attempt_id=NEW.attempt_id AND intent_id=i.intent_id AND provider=NEW.provider)
        OR (NEW.provider='VNPAY' AND NOT EXISTS(
            SELECT 1 FROM og_compat.payment_ipn_events e JOIN og_compat.payment_ipn_raw_receipts r USING(receipt_id)
            WHERE e.event_id=NEW.ipn_event_id AND e.attempt_id=NEW.attempt_id AND e.intent_id=i.intent_id
                AND r.verification_status='VERIFIED' AND e.vnp_amount=NEW.amount
                AND e.processing_outcome IN ('APPLIED_SUCCESS','APPLIED_EXPIRED_ORDER','APPLIED_DUPLICATE_CHARGE'))) THEN
        RAISE EXCEPTION 'Confirmation source/amount/reference not verified' USING ERRCODE='23514';
    END IF;
    NEW.confirmed_at:=clock_timestamp();
    IF i.state<>'PENDING' OR NEW.confirmed_at>=i.deadline OR
       (i.group_id IS NOT NULL AND EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=i.group_id AND status='CANCELLED')) THEN
        NEW.disposition:='RECONCILIATION';
    END IF;
    IF NEW.disposition='ALLOCATABLE' THEN
        UPDATE og_compat.payment_intents SET state='CONFIRMED' WHERE intent_id=i.intent_id;
        IF i.purpose='LISTING_FEE' THEN
            INSERT INTO og_compat.listing_fee_receipts(receipt_id,charge_id,provider,provider_transaction_id,amount,confirmed_at)
                VALUES(NEW.confirmation_id,i.listing_charge_id,NEW.provider,NEW.provider_transaction_id,NEW.amount,NEW.confirmed_at);
        END IF;
    ELSE
        UPDATE og_compat.payment_intents SET state='RECONCILIATION' WHERE intent_id=i.intent_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_payment_intent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_payment_intent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NEW.purpose='CHECKOUT_GROUP' AND NOT EXISTS(
        SELECT 1 FROM og_compat.checkout_groups WHERE group_id=NEW.group_id AND expected_total=NEW.expected_amount
            AND payment_due_at=NEW.deadline AND payment_method=NEW.payment_method) THEN
        RAISE EXCEPTION 'Payment amount/deadline/method differs from checkout' USING ERRCODE='23514';
    END IF;
    IF NEW.purpose='LISTING_FEE' AND NOT EXISTS(
        SELECT 1 FROM og_compat.listing_fee_charges WHERE charge_id=NEW.listing_charge_id AND amount=NEW.expected_amount) THEN
        RAISE EXCEPTION 'Payment differs from listing fee charge' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' AND ROW(NEW.purpose,NEW.group_id,NEW.listing_charge_id,NEW.expected_amount,NEW.currency,
        NEW.payment_method,NEW.deadline,NEW.created_at,NEW.command_key)
        IS DISTINCT FROM ROW(OLD.purpose,OLD.group_id,OLD.listing_charge_id,OLD.expected_amount,OLD.currency,
        OLD.payment_method,OLD.deadline,OLD.created_at,OLD.command_key) THEN
        RAISE EXCEPTION 'Payment intent snapshot is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_penalty_entry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_penalty_entry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE points BIGINT;
BEGIN
    PERFORM 1 FROM og_compat.users WHERE user_id=NEW.user_id FOR UPDATE;
    SELECT COALESCE(sum(points_delta),0) INTO points FROM og_compat.penalty_ledger WHERE user_id=NEW.user_id;
    IF NOT og_has_role(NEW.decided_by,'KTV') OR points+NEW.points_delta<0
        OR (NEW.points_delta>0 AND NOT EXISTS(SELECT 1 FROM og_compat.reports
            WHERE report_id=NEW.report_id AND status='RESOLVED'))
        OR (NEW.adjustment_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.penalty_ledger
            WHERE entry_id=NEW.adjustment_of AND user_id=NEW.user_id)) THEN
        RAISE EXCEPTION 'Penalty requires confirmed KTV violation/correction' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_pickup_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_pickup_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE s og_compat.shipments;
BEGIN
    SELECT * INTO STRICT s FROM og_compat.shipments WHERE shipment_id=NEW.shipment_id FOR UPDATE;
    IF s.workflow_model<>'UC83' OR s.leg<>'RETURN' OR NEW.attempted_at<s.initiated_at OR NEW.attempted_at>s.pickup_deadline
       OR NEW.attempt_no<>(SELECT count(*)+1 FROM og_compat.pickup_attempts WHERE shipment_id=s.shipment_id)
       OR (SELECT count(*) FROM og_compat.pickup_attempts WHERE shipment_id=s.shipment_id AND outcome='FAILED')>=3
       OR EXISTS(SELECT 1 FROM og_compat.pickup_attempts WHERE shipment_id=s.shipment_id AND outcome='PICKED_UP')
       OR NOT EXISTS(SELECT 1 FROM og_compat.shipment_events WHERE event_id=NEW.source_event_id AND shipment_id=s.shipment_id) THEN
        RAISE EXCEPTION 'Pickup deadline/count/source exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_private_asset(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_private_asset() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF TG_OP='DELETE' OR (TG_OP='UPDATE' AND ROW(NEW.profile_id,NEW.asset_type,NEW.object_key,
        NEW.content_digest,NEW.captured_at,NEW.expires_at) IS DISTINCT FROM
        ROW(OLD.profile_id,OLD.asset_type,OLD.object_key,OLD.content_digest,OLD.captured_at,OLD.expires_at)) THEN
        RAISE EXCEPTION 'Private evidence identity retained; mark deletion only' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles WHERE profile_id=NEW.profile_id
        AND state IN ('DRAFT','IN_PROGRESS')) THEN
        RAISE EXCEPTION 'Only open eKYC accepts new evidence' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_product_revision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_product_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.provenance='UC83' AND NEW.state<>'DRAFT' THEN
            RAISE EXCEPTION 'UC83 revision starts as draft' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.state<>'DRAFT' THEN
        RAISE EXCEPTION 'Product revision history is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state='SUBMITTED' AND (
        (SELECT count(*) FROM og_compat.revision_media WHERE revision_id=NEW.revision_id AND media_type='IMAGE') NOT BETWEEN 1 AND 5
        OR (SELECT count(*) FROM og_compat.revision_media WHERE revision_id=NEW.revision_id AND media_type='VIDEO') NOT BETWEEN 1 AND 2) THEN
        RAISE EXCEPTION 'Submission requires images and videos' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_quick_auth(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_quick_auth() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles p JOIN og_compat.ekyc_decisions d USING(profile_id)
        JOIN og_compat.ekyc_private_assets a ON a.profile_id=p.profile_id
        WHERE p.profile_id=NEW.profile_id AND p.state='VERIFIED' AND d.outcome='VERIFIED'
          AND a.asset_id=NEW.reference_asset_id AND a.asset_type='REFERENCE' AND a.deleted_at IS NULL
          AND NEW.expires_at<=LEAST(a.expires_at,p.reference_expires_at)
          AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles pending WHERE pending.user_id=NEW.user_id
                         AND pending.state IN ('DRAFT','IN_PROGRESS','PENDING'))) THEN
        RAISE EXCEPTION 'Quick auth requires current approved private reference' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_quick_auth_attempt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_quick_auth_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE s og_compat.quick_auth_sessions;
BEGIN
    SELECT * INTO STRICT s FROM og_compat.quick_auth_sessions WHERE session_id=NEW.session_id FOR UPDATE;
    NEW.attempted_at:=clock_timestamp();
    IF s.expires_at<=NEW.attempted_at OR s.nonmatch_count>=15 OR EXISTS(SELECT 1 FROM og_compat.quick_auth_attempts
        WHERE session_id=s.session_id AND result='MATCH') OR NOT EXISTS(
        SELECT 1 FROM og_compat.ekyc_profiles p JOIN og_compat.ekyc_decisions d USING(profile_id)
        JOIN og_compat.ekyc_private_assets a ON a.profile_id=p.profile_id WHERE p.profile_id=s.profile_id
          AND p.state='VERIFIED' AND d.outcome='VERIFIED' AND p.reference_expires_at>NEW.attempted_at
          AND a.asset_id=s.reference_asset_id AND a.asset_type='REFERENCE' AND a.deleted_at IS NULL
          AND a.expires_at>NEW.attempted_at
          AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_profiles pending WHERE pending.user_id=s.user_id
              AND pending.state IN ('DRAFT','IN_PROGRESS','PENDING'))) THEN
        RAISE EXCEPTION 'Quick authentication unavailable/exhausted' USING ERRCODE='23514';
    END IF;
    IF s.last_nonmatch_at IS NOT NULL AND NEW.attempted_at<s.last_nonmatch_at+INTERVAL '3 seconds' THEN
        RAISE EXCEPTION 'Quick authentication cooldown' USING ERRCODE='23514';
    END IF;
    IF NEW.result='NON_MATCH' THEN UPDATE og_compat.quick_auth_sessions SET nonmatch_count=nonmatch_count+1,
        last_nonmatch_at=NEW.attempted_at WHERE session_id=s.session_id; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_return_case(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_return_case() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders;
BEGIN
    IF NEW.state<>'OPEN' THEN RAISE EXCEPTION 'New case starts open' USING ERRCODE='23514'; END IF;
    IF NEW.case_type='RETURN' AND TG_OP='INSERT' THEN
        SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id FOR UPDATE;
        NEW.created_at:=clock_timestamp();
        IF o.workflow_model<>'UC83' OR NEW.created_by<>o.buyer_id OR NOT o.return_allowed
            OR o.valid_delivered_at IS NULL OR o.early_completed_at IS NOT NULL
            OR NEW.created_at>o.valid_delivered_at+INTERVAL '3 days' THEN
            RAISE EXCEPTION 'Order has no current right to request return' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_return_shipment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_return_shipment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.cases;
BEGIN
    IF NEW.workflow_model='UC83' AND NEW.leg='RETURN' THEN
        SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.return_case_id FOR UPDATE;
        IF c.order_id<>NEW.order_id OR c.case_type<>'RETURN' OR c.approved_at IS NULL THEN
            RAISE EXCEPTION 'Return shipment requires approval for the same order' USING ERRCODE='23514';
        END IF;
        NEW.pickup_expected_at:=c.approved_at+INTERVAL '24 hours';
        NEW.pickup_deadline:=c.approved_at+INTERVAL '3 days';
    END IF;
    IF TG_OP='UPDATE' AND NEW.workflow_model='UC83' AND
        ROW(NEW.order_id,NEW.leg,NEW.return_case_id,NEW.delivery_method,NEW.initiated_at)
        IS DISTINCT FROM ROW(OLD.order_id,OLD.leg,OLD.return_case_id,OLD.delivery_method,OLD.initiated_at) THEN
        RAISE EXCEPTION 'Shipment identity/method snapshot cannot silently change' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_review_parties(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_review_parties() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders;
BEGIN
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id;
    IF NOT ((NEW.reviewer_id=o.buyer_id AND NEW.reviewee_id=o.seller_id)
        OR (NEW.reviewer_id=o.seller_id AND NEW.reviewee_id=o.buyer_id))
        OR (o.workflow_model='UC83' AND o.valid_delivered_at IS NULL)
        OR (o.workflow_model='LEGACY_V14' AND o.status NOT IN ('DELIVERED','COMPLETED')) THEN
        RAISE EXCEPTION 'Review requires delivered order and its two parties' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF ROW(NEW.order_id,NEW.reviewer_id,NEW.reviewee_id) IS DISTINCT FROM ROW(OLD.order_id,OLD.reviewer_id,OLD.reviewee_id) THEN
            RAISE EXCEPTION 'Review identity immutable' USING ERRCODE='23514';
        END IF;
        INSERT INTO og_compat.review_revisions(review_id,original_record) VALUES(OLD.review_id,to_jsonb(OLD));
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_revision_media(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_revision_media() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE parent og_compat.product_revisions; n INTEGER;
BEGIN
    IF TG_OP<>'INSERT' THEN
        SELECT * INTO STRICT parent FROM og_compat.product_revisions WHERE revision_id=OLD.revision_id FOR UPDATE;
        IF parent.state<>'DRAFT' THEN
            RAISE EXCEPTION 'Submitted revision media is immutable' USING ERRCODE='23514';
        END IF;
        IF TG_OP='DELETE' THEN RETURN OLD; END IF;
        IF NEW.revision_id<>OLD.revision_id THEN
            RAISE EXCEPTION 'Cannot move media between revisions' USING ERRCODE='23514';
        END IF;
    ELSE
        SELECT * INTO STRICT parent FROM og_compat.product_revisions WHERE revision_id=NEW.revision_id FOR UPDATE;
    END IF;
    IF parent.state<>'DRAFT' OR parent.provenance<>'UC83' THEN
        RAISE EXCEPTION 'Only current draft accepts media' USING ERRCODE='23514';
    END IF;
    SELECT count(*) INTO n FROM og_compat.revision_media WHERE revision_id=NEW.revision_id
        AND media_type=NEW.media_type AND revision_media_id IS DISTINCT FROM NEW.revision_media_id;
    IF n >= (CASE NEW.media_type WHEN 'IMAGE' THEN 5 ELSE 2 END) THEN
        RAISE EXCEPTION 'Revision media count exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_reward_account(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_reward_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' OR (TG_OP='INSERT' AND (NEW.balance<>0 OR NEW.version<>0))
        OR (TG_OP='UPDATE' AND (NEW.user_id<>OLD.user_id OR pg_trigger_depth()<2)) THEN
        RAISE EXCEPTION 'Reward balance only changes through ledger' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_seller_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_seller_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' OR NEW.user_id<>OLD.user_id OR NEW.revision_no<OLD.revision_no
        OR (OLD.state IN ('APPROVED','REJECTED') AND NEW.revision_no=OLD.revision_no AND
            ROW(NEW.state,NEW.ekyc_profile_id,NEW.quick_auth_result_id,NEW.pickup_address_id,NEW.bank_snapshot)
            IS DISTINCT FROM ROW(OLD.state,OLD.ekyc_profile_id,OLD.quick_auth_result_id,OLD.pickup_address_id,OLD.bank_snapshot))
        OR (NEW.revision_no>OLD.revision_no AND (NEW.revision_no<>OLD.revision_no+1 OR NEW.state NOT IN ('PENDING_EKYC','PENDING_REVIEW'))) THEN
        RAISE EXCEPTION 'Seller snapshot changes require a new review revision' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_settlement_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_settlement_operation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.order_fund_components; o og_compat.orders; old_reserved BOOLEAN; new_reserved BOOLEAN;
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Settlement history retained' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=(SELECT order_id FROM og_compat.order_fund_components WHERE component_id=NEW.component_id) FOR UPDATE;
    SELECT * INTO STRICT c FROM og_compat.order_fund_components WHERE component_id=NEW.component_id FOR UPDATE;
    IF TG_OP='INSERT' AND NEW.state<>'REQUESTED' THEN RAISE EXCEPTION 'Operation starts requested' USING ERRCODE='23514'; END IF;
    IF TG_OP='UPDATE' AND (OLD.state='CONFIRMED' OR
        ROW(NEW.component_id,NEW.operation_type,NEW.amount,NEW.cause_type,NEW.case_decision_id,NEW.recipient_user_id,NEW.command_key)
        IS DISTINCT FROM ROW(OLD.component_id,OLD.operation_type,OLD.amount,OLD.cause_type,OLD.case_decision_id,OLD.recipient_user_id,OLD.command_key)) THEN
        RAISE EXCEPTION 'Settlement identity/confirmed result immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.state IN ('REQUESTED','PROCESSING','CONFIRMED') THEN
        IF EXISTS(SELECT 1 FROM og_compat.money_holds WHERE component_id=c.component_id AND closed_at IS NULL) THEN
            RAISE EXCEPTION 'Money component has active hold' USING ERRCODE='23514';
        END IF;
        IF c.component_type IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY') AND og_order_has_blocking_case(o.order_id) THEN
            RAISE EXCEPTION 'Order has blocking case' USING ERRCODE='23514';
        END IF;
        IF NEW.operation_type='REFUND_BUYER' THEN
            IF NEW.recipient_user_id IS DISTINCT FROM o.buyer_id OR c.component_type NOT IN ('GOODS_CASH','SHIPPING_CASH','LATE_PAYMENT_CASH')
              OR NEW.amount<>c.confirmed_amount
              OR (c.component_type='SHIPPING_CASH' AND (NEW.cause_type<>'CANCELLATION' OR o.purchase_shipping_used_at IS NOT NULL))
              OR NOT ((NEW.cause_type='CANCELLATION' AND o.status='CANCELLED')
                OR (NEW.cause_type='RETURN' AND og_case_settlement_allowed(NEW.case_decision_id,o.order_id,'RETURN'))
                OR (NEW.cause_type='RECONCILIATION' AND c.component_type='LATE_PAYMENT_CASH')) THEN
                RAISE EXCEPTION 'Buyer refund not eligible/full net component' USING ERRCODE='23514';
            END IF;
        ELSIF NEW.operation_type='RELEASE_SELLER' THEN
            IF NEW.recipient_user_id IS DISTINCT FROM o.seller_id
                OR c.component_type NOT IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY')
                OR NOT ((NEW.cause_type='COMPLETION' AND o.valid_delivered_at IS NOT NULL
                    AND (o.early_completed_at IS NOT NULL OR clock_timestamp()>=o.valid_delivered_at+INTERVAL '3 days'))
                    OR (NEW.cause_type='EXEMPTION' AND og_case_settlement_allowed(NEW.case_decision_id,o.order_id,'EXEMPTION'))) THEN
                RAISE EXCEPTION 'Seller release is not eligible' USING ERRCODE='23514';
            END IF;
        ELSIF NEW.operation_type='RELEASE_CARRIER' THEN
            IF c.component_type NOT IN ('SHIPPING_CASH','PLATFORM_SHIPPING_SUBSIDY') OR o.purchase_shipping_used_at IS NULL THEN
                RAISE EXCEPTION 'Shipping was not used' USING ERRCODE='23514';
            END IF;
        ELSIF c.component_type NOT LIKE 'PLATFORM_%' OR NOT (
            (NEW.cause_type='CANCELLATION' AND o.status='CANCELLED') OR
            (NEW.cause_type='RETURN' AND og_case_settlement_allowed(NEW.case_decision_id,o.order_id,'RETURN'))) THEN
            RAISE EXCEPTION 'Platform return requires subsidy component' USING ERRCODE='23514';
        END IF;
    END IF;
    old_reserved:=TG_OP='UPDATE' AND OLD.state IN ('REQUESTED','PROCESSING');
    new_reserved:=NEW.state IN ('REQUESTED','PROCESSING');
    IF (TG_OP='INSERT' OR (TG_OP='UPDATE' AND OLD.state='FAILED')) AND new_reserved THEN
        UPDATE og_compat.order_fund_components SET reserved_amount=reserved_amount+NEW.amount,version=version+1
            WHERE component_id=c.component_id;
    ELSIF old_reserved AND NEW.state IN ('FAILED','CONFIRMED') THEN
        UPDATE og_compat.order_fund_components SET reserved_amount=reserved_amount-NEW.amount,
            refunded_amount=refunded_amount+CASE WHEN NEW.state='CONFIRMED' AND NEW.operation_type IN ('REFUND_BUYER','RETURN_PLATFORM') THEN NEW.amount ELSE 0 END,
            released_amount=released_amount+CASE WHEN NEW.state='CONFIRMED' AND NEW.operation_type IN ('RELEASE_SELLER','RELEASE_CARRIER') THEN NEW.amount ELSE 0 END,
            version=version+1 WHERE component_id=c.component_id;
    ELSIF TG_OP='UPDATE' AND NEW.state<>OLD.state AND NOT (OLD.state='REQUESTED' AND NEW.state='PROCESSING') THEN
        RAISE EXCEPTION 'Invalid settlement transition' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_voucher_grant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_voucher_grant() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE r og_compat.voucher_revisions;
BEGIN
    SELECT * INTO STRICT r FROM og_compat.voucher_revisions WHERE revision_id=NEW.revision_id FOR UPDATE;
    IF NEW.state<>'AVAILABLE' OR NEW.expires_at>r.valid_until OR NEW.expires_at<=NEW.granted_at
        OR EXISTS(SELECT 1 FROM og_compat.voucher_revision_revocations WHERE revision_id=r.revision_id)
        OR NEW.granted_at<r.valid_from OR NEW.granted_at>=r.valid_until
        OR (NEW.source='SELF_CLAIM' AND NEW.issued_by<>NEW.user_id)
        OR (NEW.source<>'SELF_CLAIM' AND (NOT og_has_role(NEW.issued_by,'KTV') OR NULLIF(btrim(NEW.reason),'') IS NULL))
        OR (SELECT count(*) FROM og_compat.voucher_grants WHERE revision_id=r.revision_id AND user_id=NEW.user_id)>=r.per_user_claim_limit
        OR (r.claim_limit IS NOT NULL AND (SELECT count(*) FROM og_compat.voucher_grants WHERE revision_id=r.revision_id)>=r.claim_limit) THEN
        RAISE EXCEPTION 'Voucher grant not eligible or claim limit exceeded' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_voucher_policy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_voucher_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE v og_compat.vouchers;
BEGIN
    SELECT * INTO STRICT v FROM og_compat.vouchers WHERE voucher_id=NEW.voucher_id;
    IF NOT og_has_role(NEW.created_by,'ADMIN') OR v.voucher_type='BUYER_FEE_DISCOUNT' THEN
        RAISE EXCEPTION 'Admin authors canonical goods/shipping policies' USING ERRCODE='23514'; END IF;
    NEW.benefit_component:=COALESCE(NEW.benefit_component,CASE v.voucher_type WHEN 'SHIPPING_DISCOUNT' THEN 'SHIPPING' ELSE 'GOODS' END);
    NEW.discount_type:=COALESCE(NEW.discount_type,v.discount_type);
    NEW.discount_value:=COALESCE(NEW.discount_value,v.discount_value);
    NEW.max_discount_amount:=COALESCE(NEW.max_discount_amount,v.max_discount_amount);
    NEW.min_eligible_amount:=COALESCE(NEW.min_eligible_amount,v.min_order_amount);
    RETURN NEW;
END;
$$;


--
-- Name: og_guard_voucher_revocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_guard_voucher_revocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    PERFORM 1 FROM og_compat.voucher_revisions WHERE revision_id=NEW.revision_id FOR UPDATE;
    IF NOT og_has_role(NEW.revoked_by,'ADMIN') THEN RAISE EXCEPTION 'Admin revokes policy' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_has_role(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_has_role(p_user bigint, p_role text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', '$user', 'public'
    AS $$
    SELECT EXISTS (SELECT 1 FROM og_compat.user_roles ur JOIN og_compat.roles r USING(role_id) JOIN og_compat.users u USING(user_id)
                   WHERE ur.user_id = p_user AND r.role_name = p_role AND u.status='ACTIVE' AND u.deleted_at IS NULL)
$$;


--
-- Name: og_hold_new_case_component(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_hold_new_case_component() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NEW.component_type IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY') THEN
        INSERT INTO og_compat.money_holds(hold_id,component_id,source_key,reason,case_id)
            SELECT gen_random_uuid(),NEW.component_id,'RETURN_CASE:'||case_id,'Return case pending',case_id
            FROM og_compat.cases WHERE order_id=NEW.order_id AND case_type='RETURN' AND state NOT IN ('CLOSED','REJECTED');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_lock_money_hold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_lock_money_hold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    PERFORM 1 FROM og_compat.orders WHERE order_id=(SELECT order_id FROM og_compat.order_fund_components WHERE component_id=NEW.component_id) FOR UPDATE;
    PERFORM 1 FROM og_compat.order_fund_components WHERE component_id=NEW.component_id FOR UPDATE;
    IF TG_OP='UPDATE' AND (NEW.component_id<>OLD.component_id OR NEW.source_key<>OLD.source_key
       OR OLD.closed_at IS NOT NULL) THEN RAISE EXCEPTION 'Hold history is immutable' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_order_has_blocking_case(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_order_has_blocking_case(p_order bigint) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public', '$user', 'public'
    AS $$
    SELECT EXISTS(SELECT 1 FROM og_compat.cases WHERE order_id=p_order AND state NOT IN ('CLOSED','REJECTED'))
$$;


--
-- Name: og_record_account_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_record_account_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
        INSERT INTO og_compat.account_status_events(user_id,old_status,new_status)
            VALUES(NEW.user_id,CASE WHEN TG_OP='UPDATE' THEN OLD.status ELSE NULL END,NEW.status);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_redeem_voucher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_redeem_voucher() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE v og_compat.voucher_grants; r og_compat.voucher_revisions; base NUMERIC; benefit NUMERIC;
BEGIN
    SELECT * INTO STRICT v FROM og_compat.voucher_grants WHERE grant_id=NEW.grant_id FOR UPDATE;
    SELECT * INTO STRICT r FROM og_compat.voucher_revisions WHERE revision_id=v.revision_id FOR UPDATE;
    IF v.state<>'AVAILABLE' OR v.expires_at<=NEW.redeemed_at THEN
        RAISE EXCEPTION 'Voucher already used/revoked/expired' USING ERRCODE='23514';
    END IF;
    IF r.benefit_component='GOODS' THEN
        SELECT COALESCE(sum(i.agreed_price*i.quantity),0) INTO base FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id)
            WHERE o.group_id=NEW.group_id AND (r.scope='CHECKOUT' OR EXISTS(SELECT 1 FROM og_compat.voucher_revision_products
                WHERE revision_id=r.revision_id AND product_id=i.product_id));
    ELSE SELECT COALESCE(sum(shipping_fee),0) INTO base FROM og_compat.orders WHERE group_id=NEW.group_id; END IF;
    benefit:=LEAST(base,CASE WHEN r.discount_type='FIXED_AMOUNT' THEN r.discount_value
        ELSE round(base*r.discount_value/100,0) END,COALESCE(r.max_discount_amount,base));
    IF base<r.min_eligible_amount OR NEW.discount_amount<>benefit OR EXISTS(
        SELECT 1 FROM og_compat.voucher_revision_revocations WHERE revision_id=r.revision_id) THEN
        RAISE EXCEPTION 'Voucher amount/minimum/revocation differs from immutable policy' USING ERRCODE='23514'; END IF;
    NEW.policy_snapshot:=r.policy_snapshot||jsonb_build_object('benefit_component',r.benefit_component,
        'discount_type',r.discount_type,'discount_value',r.discount_value,'max_discount_amount',r.max_discount_amount,
        'min_eligible_amount',r.min_eligible_amount,'scope',r.scope);
    UPDATE og_compat.voucher_grants SET state='REDEEMED' WHERE grant_id=v.grant_id;
    RETURN NEW;
END;
$$;


