--
-- Name: og_return_case_money_holds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_return_case_money_holds() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NEW.case_type='RETURN' THEN
        INSERT INTO og_compat.money_holds(hold_id,component_id,source_key,reason,case_id)
            SELECT gen_random_uuid(),f.component_id,'RETURN_CASE:'||NEW.case_id,'Return case pending',NEW.case_id FROM og_compat.order_fund_components f WHERE f.order_id=NEW.order_id AND f.component_type IN ('GOODS_CASH','PLATFORM_GOODS_SUBSIDY') AND NOT EXISTS(SELECT 1 FROM og_compat.money_holds h WHERE h.component_id=f.component_id AND h.source_key='RETURN_CASE:'||NEW.case_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: og_validate_canonical_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_canonical_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE role_code TEXT;
BEGIN
    IF NOT EXISTS(SELECT 1 FROM og_compat.users WHERE user_id=NEW.user_id AND identity_workflow='UC83') THEN RETURN NULL; END IF;
    SELECT role_name INTO role_code FROM og_compat.roles WHERE role_id=NEW.role_id;
    IF (role_code='SELLER' AND NOT EXISTS(SELECT 1 FROM og_compat.seller_profiles p JOIN og_compat.seller_profile_decisions d USING(seller_profile_id)
        WHERE p.user_id=NEW.user_id AND p.state='APPROVED' AND p.revision_no=d.revision_no AND d.outcome='APPROVED'))
        OR (role_code IN ('KTV','ADMIN') AND NOT og_has_role(NEW.granted_by,'ADMIN')) THEN
        RAISE EXCEPTION 'Canonical role grant requires approval authority' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_case_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_case_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE c og_compat.cases;
BEGIN
    SELECT * INTO STRICT c FROM og_compat.cases WHERE case_id=NEW.case_id;
    IF (c.approved_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.case_decisions d JOIN og_compat.case_rounds r USING(round_id)
        WHERE r.case_id=c.case_id AND d.outcome='APPROVE_RETURN' AND d.is_final))
        OR (c.state IN ('CLOSED','REJECTED') AND NOT EXISTS(SELECT 1 FROM og_compat.case_decisions d JOIN og_compat.case_rounds r USING(round_id)
            WHERE r.case_id=c.case_id AND d.is_final AND d.outcome IN
                ('REJECT_RETURN','FULL_GOODS_REFUND','EXEMPT_GOODS_REFUND','SYSTEM_RESOLVED')))
        OR (c.valid_returned_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.shipments s
            WHERE s.return_case_id=c.case_id AND s.leg='RETURN' AND s.valid_delivery_at=c.valid_returned_at)) THEN
        RAISE EXCEPTION 'Case state requires corresponding decision/delivery proof' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_checkout_aggregate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_checkout_aggregate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE g og_compat.checkout_groups; gid UUID; o og_compat.orders; n INTEGER;
BEGIN
    IF TG_TABLE_NAME='checkout_groups' THEN gid:=NEW.group_id;
    ELSIF TG_TABLE_NAME='orders' THEN gid:=NEW.group_id;
    ELSE SELECT group_id INTO gid FROM og_compat.orders WHERE order_id=NEW.order_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    SELECT * INTO STRICT g FROM og_compat.checkout_groups WHERE group_id=gid FOR UPDATE;
    IF g.expected_total<>(SELECT COALESCE(sum(total_amount),0) FROM og_compat.orders WHERE group_id=gid)
       OR NOT EXISTS(SELECT 1 FROM og_compat.orders WHERE group_id=gid) THEN
        RAISE EXCEPTION 'Checkout total must equal all orders' USING ERRCODE='23514';
    END IF;
    FOR o IN SELECT * FROM og_compat.orders WHERE group_id=gid LOOP
        IF o.payment_due_at<>g.payment_due_at OR o.delivery_method<>g.delivery_method
            OR o.carrier_snapshot IS DISTINCT FROM g.carrier
            OR jsonb_build_object('recipient_name',o.shipping_recipient_name,'phone_number',o.shipping_phone_number,
                'province',o.shipping_province,'district',o.shipping_district,'ward',o.shipping_ward,
                'detail_address',o.shipping_detail_address)<>g.address_snapshot
            OR o.subtotal<>(SELECT COALESCE(sum(agreed_price*quantity),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR o.voucher_discount_amount<>(SELECT COALESCE(sum(voucher_allocation),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR o.points_discount_amount<>(SELECT COALESCE(sum(points_allocation),0) FROM og_compat.order_items WHERE order_id=o.order_id)
            OR EXISTS(SELECT 1 FROM og_compat.order_items i WHERE i.order_id=o.order_id AND NOT EXISTS(
                SELECT 1 FROM og_compat.inventory_reservations r WHERE r.order_item_id=i.order_item_id AND r.quantity=i.quantity)) THEN
            RAISE EXCEPTION 'Checkout snapshots/items/reservations incomplete' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_discount_totals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_discount_totals() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE gid UUID; v NUMERIC; p NUMERIC;
BEGIN
    IF TG_TABLE_NAME IN ('checkout_groups','orders','checkout_redemptions','reward_ledger') THEN gid:=NEW.group_id;
    ELSE SELECT o.group_id INTO gid FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id) WHERE i.order_item_id=NEW.order_item_id; END IF;
    IF gid IS NULL THEN RETURN NULL; END IF;
    PERFORM 1 FROM og_compat.checkout_groups WHERE group_id=gid FOR UPDATE;
    SELECT COALESCE(sum(voucher_discount_amount+shipping_discount_amount),0),COALESCE(sum(points_discount_amount),0)
        INTO v,p FROM og_compat.orders WHERE group_id=gid;
    IF v<>COALESCE((SELECT discount_amount FROM og_compat.checkout_redemptions WHERE group_id=gid),0)
        OR p<>COALESCE((SELECT -l.points_delta*r.point_value FROM og_compat.reward_ledger l JOIN og_compat.reward_policies r USING(policy_id)
            WHERE l.group_id=gid AND l.entry_type='DEBIT_CHECKOUT'),0)
        OR EXISTS(SELECT 1 FROM og_compat.order_items i JOIN og_compat.orders o USING(order_id) WHERE o.group_id=gid AND (
            i.voucher_allocation<>(SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations d WHERE d.order_item_id=i.order_item_id
                AND redemption_id IS NOT NULL AND component='GOODS')
            OR i.points_allocation<>(SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations d WHERE d.order_item_id=i.order_item_id
                AND reward_entry_id IS NOT NULL)))
        OR EXISTS(SELECT 1 FROM og_compat.orders o WHERE o.group_id=gid AND o.shipping_discount_amount<>(
            SELECT COALESCE(sum(d.amount),0) FROM og_compat.discount_allocations d JOIN og_compat.order_items i USING(order_item_id)
            WHERE i.order_id=o.order_id AND d.component='SHIPPING'))
        OR EXISTS(SELECT 1 FROM og_compat.checkout_redemptions c WHERE c.group_id=gid AND c.discount_amount<>(
            SELECT COALESCE(sum(amount),0) FROM og_compat.discount_allocations WHERE redemption_id=c.redemption_id)) THEN
        RAISE EXCEPTION 'Voucher/points allocations must exactly conserve checkout discounts' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_identity_decision(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_identity_decision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF TG_TABLE_NAME='ekyc_profiles' THEN
        IF EXISTS(SELECT 1 FROM og_compat.ekyc_profiles p WHERE p.profile_id=NEW.profile_id
            AND p.state IN ('VERIFIED','REJECTED') AND NOT EXISTS(SELECT 1 FROM og_compat.ekyc_decisions d
                WHERE d.profile_id=p.profile_id AND d.outcome=p.state)) THEN
            RAISE EXCEPTION 'Final eKYC state requires KTV decision' USING ERRCODE='23514';
        END IF;
    ELSE
        IF EXISTS(SELECT 1 FROM og_compat.seller_profiles p WHERE p.seller_profile_id=NEW.seller_profile_id
            AND p.state IN ('APPROVED','REJECTED') AND NOT EXISTS(SELECT 1 FROM og_compat.seller_profile_decisions d
                WHERE d.seller_profile_id=p.seller_profile_id AND d.revision_no=p.revision_no AND d.outcome=p.state)) THEN
            RAISE EXCEPTION 'Final seller state requires KTV decision' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_intent_confirmation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_intent_confirmation() RETURNS trigger
    LANGUAGE plpgsql
