        AND NOT EXISTS(SELECT 1 FROM og_compat.listing_fee_receipts r WHERE r.charge_id=c.charge_id AND r.amount=c.amount)) THEN
        RAISE EXCEPTION 'Confirmed charge requires exact receipt' USING ERRCODE='23514';
