--
-- Name: og_validate_order_workflow_proof(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_order_workflow_proof() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE o og_compat.orders;
BEGIN
    SELECT * INTO STRICT o FROM og_compat.orders WHERE order_id=NEW.order_id;
    IF o.workflow_model='UC83' AND (
        (o.paid_confirmed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.payment_allocations a
            JOIN og_compat.payment_confirmations c USING(confirmation_id) WHERE a.order_id=o.order_id
                AND c.disposition='ALLOCATABLE' AND c.confirmed_at=o.paid_confirmed_at)
            AND NOT (o.total_amount=0 AND EXISTS(SELECT 1 FROM og_compat.zero_checkout_confirmations z
                WHERE z.group_id=o.group_id AND z.buyer_id=o.buyer_id AND z.confirmed_at=o.paid_confirmed_at)))
        OR (o.valid_delivered_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.shipments s WHERE s.order_id=o.order_id
            AND s.leg='OUTBOUND' AND s.valid_delivery_at=o.valid_delivered_at))
        OR (o.early_completed_at IS NOT NULL AND NOT EXISTS(SELECT 1 FROM og_compat.order_events e WHERE e.order_id=o.order_id
            AND e.actor_id=o.buyer_id AND e.event_type='EARLY_COMPLETION_ACCEPTED'))
        OR (o.seller_accept_due_at IS NOT NULL AND o.seller_accept_due_at<>
            COALESCE(o.paid_confirmed_at,o.created_at)+INTERVAL '2 days')) THEN
        RAISE EXCEPTION 'Order deadlines/payment/delivery/consent need source proof' USING ERRCODE='23514'; END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_payment_allocations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_payment_allocations() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
DECLARE i og_compat.payment_intents; n NUMERIC;
BEGIN
    SELECT * INTO STRICT i FROM og_compat.payment_intents WHERE intent_id=NEW.intent_id FOR UPDATE;
    IF i.purpose='CHECKOUT_GROUP' AND EXISTS(SELECT 1 FROM og_compat.payment_confirmations
        WHERE intent_id=i.intent_id AND disposition='ALLOCATABLE') THEN
        SELECT COALESCE(sum(amount),0) INTO n FROM og_compat.payment_allocations WHERE intent_id=i.intent_id;
        IF n<>i.expected_amount OR EXISTS(SELECT 1 FROM og_compat.orders o WHERE o.group_id=i.group_id
            AND NOT EXISTS(SELECT 1 FROM og_compat.payment_allocations a WHERE a.order_id=o.order_id AND a.intent_id=i.intent_id)) THEN
            RAISE EXCEPTION 'Confirmed payment must allocate every order exactly' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: og_validate_quick_auth_match(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.og_validate_quick_auth_match() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', '$user', 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM og_compat.quick_auth_attempts WHERE session_id=NEW.session_id AND result='MATCH'
        AND attempted_at=NEW.matched_at) OR NEW.matched_at>clock_timestamp() THEN
        RAISE EXCEPTION 'Quick authentication result requires server match' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_product_moderation_decisions_append_only(); Type: FUNCTION; Schema: public; Owner: -
