--
-- Name: reputation_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.reputation_summary AS
 SELECT u.user_id,
    COALESCE(r.average_stars, (0)::numeric) AS average_stars,
    COALESCE(r.review_count, (0)::bigint) AS review_count,
    COALESCE(p.penalty_points, (0)::bigint) AS penalty_points,
        CASE
            WHEN (r.review_count IS NULL) THEN NULL::numeric
            ELSE (r.average_stars - (COALESCE(p.penalty_points, (0)::bigint))::numeric)
        END AS reputation
   FROM ((og_compat.users u
     LEFT JOIN ( SELECT rv.reviewee_id,
            avg(rv.rating) AS average_stars,
            count(*) AS review_count
           FROM (og_compat.reviews rv
             JOIN og_compat.orders o USING (order_id))
          WHERE ((rv.deleted_at IS NULL) AND (((rv.reviewer_id = o.buyer_id) AND (rv.reviewee_id = o.seller_id)) OR ((rv.reviewer_id = o.seller_id) AND (rv.reviewee_id = o.buyer_id))) AND ((((o.workflow_model)::text = 'UC83'::text) AND (o.valid_delivered_at IS NOT NULL)) OR (((o.workflow_model)::text = 'LEGACY_V14'::text) AND ((o.status)::text = ANY (ARRAY[('DELIVERED'::character varying)::text, ('COMPLETED'::character varying)::text])))))
          GROUP BY rv.reviewee_id) r ON ((r.reviewee_id = u.user_id)))
     LEFT JOIN ( SELECT penalty_ledger.user_id,
            sum(penalty_ledger.points_delta) AS penalty_points
           FROM og_compat.penalty_ledger
          GROUP BY penalty_ledger.user_id) p ON ((p.user_id = u.user_id)));


--
-- Name: uc83_public_products; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.uc83_public_products AS
 SELECT p.product_id,
    p.seller_id,
    p.category_id,
    p.title,
    p.description,
    p.listed_price,
    p.currency,
    p.condition,
    p.usage_duration,
    p.defects,
    p.repair_history,
    p.included_accessories,
    p.location,
    p.status,
    p.reserved_until,
    p.reserved_order_id,
    p.version,
    p.created_at,
    p.updated_at,
    p.deleted_at,
    p.requires_buyer_ekyc,
    p.content_revision,
    p.workflow_model,
    p.quantity_total,
    p.quantity_held,
    p.quantity_sold,
    p.quantity_unavailable,
    p.quantity_available,
    p.return_allowed,
    p.delivery_options,
    p.current_revision_id,
    p.public_revision_id
   FROM (og_compat.products p
     JOIN og_compat.users seller ON ((seller.user_id = p.seller_id)))
  WHERE (((p.workflow_model)::text = 'UC83'::text) AND ((p.status)::text = 'ACTIVE'::text) AND (p.deleted_at IS NULL) AND (p.quantity_available > 0) AND ((seller.status)::text = 'ACTIVE'::text) AND (NOT (EXISTS ( SELECT 1
           FROM og_compat.account_restrictions ar
          WHERE ((ar.user_id = p.seller_id) AND (ar.closed_at IS NULL))))));


